tool_schemas.implementation:
def get_workspace_hierarchy(workspaceId=None, workspaceName=None, includeArchived=None, refresh=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, workspace_id=None, resolution_trace=None, warnings=None, http_status=None, clickup_request=None, clickup_response=None):
        try:
            oplog = _load("operation_log.json")
            def _new_id(prefix):
                import secrets
                return prefix + secrets.token_hex(8).upper()
            entry = {
                "id": _new_id("cu_op_"),
                "workspace_id": workspace_id,
                "tool_name": "get_workspace_hierarchy",
                "bulk_job_id": None,
                "request_params": {
                    "workspaceId": workspaceId,
                    "workspaceName": workspaceName,
                    "includeArchived": includeArchived,
                    "refresh": refresh,
                },
                "resolution_trace": resolution_trace,
                "clickup_request": clickup_request,
                "clickup_response": clickup_response,
                "http_status": http_status,
                "warnings": warnings,
                "status": status,
                "created_at": now,
                "updated_at": now,
            }
            oplog.append(entry)
            _save("operation_log.json", oplog)
        except Exception:
            pass

    # Validate inputs
    if workspaceId is not None:
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            _log("error", None, resolution_trace={"stage": "validate", "field": "workspaceId"})
            return _err("VALIDATION_ERROR", "Invalid workspaceId format; expected ^cu_wsp_[0-9A-Z]+$.")
    if workspaceName is not None and not isinstance(workspaceName, str):
        _log("error", None, resolution_trace={"stage": "validate", "field": "workspaceName"})
        return _err("VALIDATION_ERROR", "workspaceName must be a string.")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _log("error", None, resolution_trace={"stage": "validate", "field": "includeArchived"})
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean.")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", None, resolution_trace={"stage": "validate", "field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")
    if workspaceId is None and workspaceName is None:
        _log("error", None, resolution_trace={"stage": "validate"})
        return _err("VALIDATION_ERROR", "Must provide workspaceId or workspaceName.")

    workspaces = _load("workspaces.json")
    nodes = _load("nodes.json")

    # Resolve workspace
    ws = None
    trace = {"workspace": {}, "filters": {"includeArchived": bool(includeArchived) if includeArchived is not None else False, "refresh": bool(refresh) if refresh is not None else False}}
    if workspaceId is not None:
        ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
        trace["workspace"]["by"] = "workspaceId"
        trace["workspace"]["value"] = workspaceId
        if not ws:
            _log("error", None, resolution_trace=trace)
            return _err("NOT_FOUND", "Workspace not found.")
    else:
        candidates = [w for w in workspaces if w.get("name") == workspaceName]
        trace["workspace"]["by"] = "workspaceName"
        trace["workspace"]["value"] = workspaceName
        if not candidates:
            _log("error", None, resolution_trace=trace)
            return _err("NOT_FOUND", "Workspace not found.")
        # Prefer active if ambiguous
        active = [w for w in candidates if w.get("status") == "active"]
        if len(active) == 1:
            ws = active[0]
            trace["workspace"]["selected"] = ws.get("id")
            trace["workspace"]["candidates"] = [w.get("id") for w in candidates]
        elif len(candidates) == 1:
            ws = candidates[0]
            trace["workspace"]["selected"] = ws.get("id")
        else:
            _log("error", None, resolution_trace={**trace, "workspace": {**trace["workspace"], "candidates": [w.get("id") for w in candidates]}})
            return _err("CONFLICT", "workspaceName is ambiguous; multiple workspaces match.", candidates=[w.get("id") for w in candidates])

    # If workspace deleted, treat as not found for hierarchy
    if ws.get("status") == "deleted":
        _log("error", ws.get("id"), resolution_trace=trace)
        return _err("NOT_FOUND", "Workspace is deleted.")

    # Refresh behavior: rebuild snapshot from current nodes cache
    if refresh:
        # Build snapshot
        include_arch = bool(includeArchived) if includeArchived is not None else False
        ws_nodes = [n for n in nodes if n.get("workspace_id") == ws.get("id") and n.get("status") != "deleted"]
        if not include_arch:
            ws_nodes = [n for n in ws_nodes if n.get("status") != "archived" and not n.get("archived", False)]

        by_id = {n["id"]: n for n in ws_nodes if isinstance(n, dict) and n.get("id")}
        spaces = [n for n in ws_nodes if n.get("node_type") == "space" and n.get("parent_node_id") is None]
        folders = [n for n in ws_nodes if n.get("node_type") == "folder"]
        lists_ = [n for n in ws_nodes if n.get("node_type") == "list"]

        children = {}
        for n in ws_nodes:
            pid = n.get("parent_node_id")
            if pid is not None:
                children.setdefault(pid, []).append(n)

        def _node_repr(n):
            return {
                "id": n.get("id"),
                "clickupNodeId": n.get("clickup_node_id"),
                "nodeType": n.get("node_type"),
                "name": n.get("name"),
                "archived": bool(n.get("archived", False)),
                "status": n.get("status"),
            }

        def _build_space(space):
            space_obj = {**_node_repr(space), "folders": [], "lists": []}
            for ch in sorted(children.get(space["id"], []), key=lambda x: (x.get("node_type"), x.get("name") or "")):
                if ch.get("node_type") == "folder":
                    space_obj["folders"].append(_build_folder(ch))
                elif ch.get("node_type") == "list":
                    space_obj["lists"].append(_node_repr(ch))
            return space_obj

        def _build_folder(folder):
            folder_obj = {**_node_repr(folder), "lists": []}
            for ch in sorted(children.get(folder["id"], []), key=lambda x: (x.get("name") or "")):
                if ch.get("node_type") == "list":
                    folder_obj["lists"].append(_node_repr(ch))
            return folder_obj

        snapshot = {
            "workspace": {
                "id": ws.get("id"),
                "clickupWorkspaceId": ws.get("clickup_workspace_id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
            },
            "spaces": [_build_space(s) for s in sorted(spaces, key=lambda x: (x.get("name") or ""))],
            "generated_at": now,
            "includeArchived": include_arch,
            "counts": {
                "spaces": len(spaces),
                "folders": len(folders),
                "lists": len(lists_),
            }
        }

        # Persist
        for i, w in enumerate(workspaces):
            if w.get("id") == ws.get("id"):
                workspaces[i] = {**w, "hierarchy_snapshot": snapshot, "last_synced_at": now, "updated_at": now}
                ws = workspaces[i]
                break
        _save("workspaces.json", workspaces)

    # Return snapshot if present, else build on the fly without persisting
    include_arch = bool(includeArchived) if includeArchived is not None else False
    snap = ws.get("hierarchy_snapshot")
    if isinstance(snap, dict):
        # If includeArchived differs from what snapshot says, rebuild lightweight without persisting
        if bool(snap.get("includeArchived", False)) == include_arch:
            _log("success", ws.get("id"), resolution_trace=trace, http_status=200)
            return {
                "workspace": snap.get("workspace"),
                "spaces": snap.get("spaces", []),
                "meta": {
                    "workspaceId": ws.get("id"),
                    "lastSyncedAt": ws.get("last_synced_at"),
                    "generatedAt": snap.get("generated_at"),
                    "includeArchived": include_arch,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            }

    # Build on the fly
    ws_nodes = [n for n in nodes if n.get("workspace_id") == ws.get("id") and n.get("status") != "deleted"]
    if not include_arch:
        ws_nodes = [n for n in ws_nodes if n.get("status") != "archived" and not n.get("archived", False)]

    children = {}
    for n in ws_nodes:
        pid = n.get("parent_node_id")
        if pid is not None:
            children.setdefault(pid, []).append(n)

    def _node_repr(n):
        return {
            "id": n.get("id"),
            "clickupNodeId": n.get("clickup_node_id"),
            "nodeType": n.get("node_type"),
            "name": n.get("name"),
            "archived": bool(n.get("archived", False)),
            "status": n.get("status"),
        }

    def _build_folder(folder):
        folder_obj = {**_node_repr(folder), "lists": []}
        for ch in sorted(children.get(folder["id"], []), key=lambda x: (x.get("name") or "")):
            if ch.get("node_type") == "list":
                folder_obj["lists"].append(_node_repr(ch))
        return folder_obj

    def _build_space(space):
        space_obj = {**_node_repr(space), "folders": [], "lists": []}
        for ch in sorted(children.get(space["id"], []), key=lambda x: (x.get("node_type"), x.get("name") or "")):
            if ch.get("node_type") == "folder":
                space_obj["folders"].append(_build_folder(ch))
            elif ch.get("node_type") == "list":
                space_obj["lists"].append(_node_repr(ch))
        return space_obj

    spaces = [n for n in ws_nodes if n.get("node_type") == "space" and n.get("parent_node_id") is None]
    result_spaces = [_build_space(s) for s in sorted(spaces, key=lambda x: (x.get("name") or ""))]

    _log("success", ws.get("id"), resolution_trace=trace, http_status=200)
    return {
        "workspace": {
            "id": ws.get("id"),
            "clickupWorkspaceId": ws.get("clickup_workspace_id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
        },
        "spaces": result_spaces,
        "meta": {
            "workspaceId": ws.get("id"),
            "lastSyncedAt": ws.get("last_synced_at"),
            "includeArchived": include_arch,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def create_task(workspaceId=None, listId=None, listName=None, name=None, description=None, status=None, priority=None, dueAt=None, startAt=None, assigneeClickupUserIds=None, tags=None, timeEstimateMs=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    workspaces = _load("workspaces.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")

    resolution_trace = {}
    warnings = []

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string.", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss.replace("Z", "+00:00"))
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time.", field=field)

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "create_task",
            "bulk_job_id": None,
            "request_params": {
                "workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name,
                "description": description, "status": status, "priority": priority, "dueAt": dueAt,
                "startAt": startAt, "assigneeClickupUserIds": assigneeClickupUserIds, "tags": tags,
                "timeEstimateMs": timeEstimateMs
            },
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/list/{list_id}/task", "method": "POST", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    # Validate required fields
    if not isinstance(name, str) or not name.strip():
        _log("error", workspaceId, 400, {"error": "invalid_name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")

    # WorkspaceId is optional in schema, but if provided must be valid and must exist and be active/archived (not deleted)
    ws_row = None
    if workspaceId is not None:
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            _log("error", None, 400, {"error": "invalid_workspaceId"})
            return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$.", field="workspaceId")
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
        if not ws_row or ws_row.get("status") == "deleted":
            _log("error", workspaceId, 404, {"error": "workspace_not_found"})
            return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    # Must provide listId or listName (business rule)
    if listId is None and listName is None:
        _log("error", workspaceId, 400, {"error": "missing_list"})
        return _err("VALIDATION_ERROR", "Either listId or listName must be provided.", fields=["listId", "listName"])

    # Relax listId validation: accept local node id OR vendor-like numeric id string; resolve accordingly
    list_node = None
    if listId is not None:
        if not isinstance(listId, str) or not listId.strip():
            _log("error", workspaceId, 400, {"error": "invalid_listId"})
            return _err("VALIDATION_ERROR", "listId must be a non-empty string.", field="listId")
        s = listId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            list_node = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"), None)
        else:
            # Treat as vendor clickup_node_id
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"]
            if workspaceId is not None:
                candidates = [n for n in candidates if n.get("workspace_id") == workspaceId]
            if len(candidates) == 1:
                list_node = candidates[0]
                resolution_trace["listId(vendor)->listNodeId"] = {"clickup_node_id": s, "id": list_node.get("id")}
            elif len(candidates) > 1:
                _log("error", workspaceId, 409, {"error": "ambiguous_listId_vendor"})
                return _err("CONFLICT", "Ambiguous listId (vendor id) matched multiple lists in scope.", listId=s, matches=[c.get("id") for c in candidates])
            else:
                list_node = None

        if not list_node:
            _log("error", workspaceId, 404, {"error": "list_not_found", "listId": listId})
            return _err("NOT_FOUND", "List not found.", listId=listId)

    if list_node is None and listName is not None:
        if not isinstance(listName, str) or not listName.strip():
            _log("error", workspaceId, 400, {"error": "invalid_listName"})
            return _err("VALIDATION_ERROR", "listName must be a non-empty string.", field="listName")
        if workspaceId is None:
            _log("error", None, 400, {"error": "missing_workspace_for_listName"})
            return _err("VALIDATION_ERROR", "workspaceId is required when resolving listName.", field="workspaceId")
        # resolve uniquely within workspace, active lists only
        candidates = [n for n in nodes if isinstance(n, dict) and n.get("workspace_id") == workspaceId and n.get("node_type") == "list" and n.get("status") != "deleted" and (n.get("name") or "").strip() == listName.strip()]
        if len(candidates) == 0:
            _log("error", workspaceId, 404, {"error": "list_not_found_by_name"})
            return _err("NOT_FOUND", "List not found.", listName=listName)
        if len(candidates) > 1:
            resolution_trace["listName_ambiguous"] = {"listName": listName, "matches": [c.get("id") for c in candidates]}
            _log("error", workspaceId, 409, {"error": "ambiguous_listName"})
            return _err("CONFLICT", "Ambiguous listName; provide listId to disambiguate.", listName=listName, matches=[c.get("id") for c in candidates])
        list_node = candidates[0]
        resolution_trace["listName->listId"] = {"listName": listName, "id": list_node.get("id")}

    # workspaceId consistency if provided
    if ws_row is not None and list_node.get("workspace_id") != workspaceId:
        _log("error", workspaceId, 409, {"error": "workspace_list_mismatch"})
        return _err("CONFLICT", "list does not belong to workspaceId.", workspaceId=workspaceId, listId=list_node.get("id"))

    # Validate optional fields
    if description is not None and not isinstance(description, str):
        _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_description"})
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if status is not None and not isinstance(status, str):
        _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_status"})
        return _err("VALIDATION_ERROR", "status must be a string.", field="status")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_priority"})
            return _err("VALIDATION_ERROR", "priority must be an integer.", field="priority")
        if priority < 1 or priority > 4:
            _log("error", list_node.get("workspace_id"), 400, {"error": "priority_range"})
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4.", field="priority")
    if timeEstimateMs is not None:
        if not isinstance(timeEstimateMs, int):
            _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_timeEstimateMs"})
            return _err("VALIDATION_ERROR", "timeEstimateMs must be an integer.", field="timeEstimateMs")
        if timeEstimateMs < 0:
            _log("error", list_node.get("workspace_id"), 400, {"error": "timeEstimateMs_range"})
            return _err("VALIDATION_ERROR", "timeEstimateMs must be >= 0.", field="timeEstimateMs")
    if assigneeClickupUserIds is not None:
        if not isinstance(assigneeClickupUserIds, list) or any(not isinstance(x, str) for x in assigneeClickupUserIds):
            _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_assignees"})
            return _err("VALIDATION_ERROR", "assigneeClickupUserIds must be an array of strings.", field="assigneeClickupUserIds")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_tags"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    due_norm = _parse_dt(dueAt, "dueAt")
    if isinstance(due_norm, dict) and due_norm.get("error"):
        _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_dueAt"})
        return due_norm
    start_norm = _parse_dt(startAt, "startAt")
    if isinstance(start_norm, dict) and start_norm.get("error"):
        _log("error", list_node.get("workspace_id"), 400, {"error": "invalid_startAt"})
        return start_norm

    # status parameter in create_task is a status_value, not lifecycle. Always set lifecycle active.
    if status is not None and status.strip().lower() == "deleted":
        warnings.append("Provided status='deleted' treated as task status_value, not lifecycle; task will be created as active.")

    # Create task row
    workspace_id_final = list_node.get("workspace_id")
    new_task_id = _new_id("cu_tsk_", tasks_store)
    clickup_task_id = f"ctk_{_new_id('', [{'id':'X'}])[0:16].lower()}"  # deterministic-enough vendor-like id; not constrained by schema
    task_row = {
        "id": new_task_id,
        "workspace_id": workspace_id_final,
        "list_node_id": list_node.get("id"),
        "clickup_task_id": clickup_task_id,
        "name": name.strip(),
        "description": description if description is None else description,
        "status_value": status if status is None else status,
        "priority": priority,
        "due_at": due_norm,
        "start_at": start_norm,
        "closed_at": None,
        "assignee_clickup_user_ids": assigneeClickupUserIds if assigneeClickupUserIds is not None else None,
        "tags": tags if tags is not None else None,
        "time_estimate_ms": timeEstimateMs,
        "vendor_raw": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    tasks_store.append(task_row)
    _save("tasks.json", tasks_store)

    resolution_trace["destination"] = {
        "list_node_id": list_node.get("id"),
        "clickup_list_id": list_node.get("clickup_node_id"),
        "workspace_id": workspace_id_final
    }

    _log("success", workspace_id_final, 200, {"id": clickup_task_id})
    return {"task": task_row, "warnings": warnings or None, "resolution_trace": resolution_trace or None}

def get_task(workspaceId=None, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return prefix + secrets.token_hex(8).upper()

    def _log(status_outcome, workspace_id=None, resolution_trace=None, warnings=None, http_status=None, clickup_request=None, clickup_response=None):
        try:
            oplog = _load("operation_log.json")
            entry = {
                "id": _new_id("cu_op_"),
                "workspace_id": workspace_id,
                "tool_name": "get_task",
                "bulk_job_id": None,
                "request_params": {
                    "workspaceId": workspaceId,
                    "taskId": taskId,
                    "taskName": taskName,
                    "listName": listName,
                },
                "resolution_trace": resolution_trace,
                "clickup_request": clickup_request,
                "clickup_response": clickup_response,
                "http_status": http_status,
                "warnings": warnings,
                "status": status_outcome,
                "created_at": now,
                "updated_at": now,
            }
            oplog.append(entry)
            _save("operation_log.json", oplog)
        except Exception:
            pass

    # Validate
    if workspaceId is not None and (not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId)):
        _log("error", None, resolution_trace={"stage": "validate", "field": "workspaceId"})
        return _err("VALIDATION_ERROR", "Invalid workspaceId format; expected ^cu_wsp_[0-9A-Z]+$.")
    if taskId is not None and (not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]+$", taskId)):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "taskId"})
        return _err("VALIDATION_ERROR", "Invalid taskId format; expected ^cu_tsk_[0-9A-Z]+$.")
    if taskName is not None and not isinstance(taskName, str):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "taskName"})
        return _err("VALIDATION_ERROR", "taskName must be a string.")
    if listName is not None and not isinstance(listName, str):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string.")
    if taskId is None and taskName is None:
        _log("error", workspaceId, resolution_trace={"stage": "validate"})
        return _err("VALIDATION_ERROR", "Must provide taskId or taskName.")

    tasks = _load("tasks.json")
    nodes = _load("nodes.json")

    trace = {}
    task = None

    if taskId is not None:
        task = next((t for t in tasks if t.get("id") == taskId and t.get("status") != "deleted"), None)
        trace = {"task": {"by": "taskId", "value": taskId}}
        if not task:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("NOT_FOUND", "Task not found.")
        if workspaceId is not None and task.get("workspace_id") != workspaceId:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("NOT_FOUND", "Task not found in specified workspace.")
    else:
        if workspaceId is None:
            _log("error", None, resolution_trace={"stage": "resolve", "need": "workspaceId for taskName resolution"})
            return _err("VALIDATION_ERROR", "workspaceId is required when resolving taskName.")
        # Gather candidates by name in workspace
        candidates = [t for t in tasks if t.get("workspace_id") == workspaceId and t.get("status") != "deleted" and t.get("name") == taskName]
        trace = {"task": {"by": "taskName", "value": taskName, "candidates": [c.get("id") for c in candidates]}, "list": {}}
        if listName is not None:
            # resolve listName within workspace; must be unique active list
            list_candidates = [n for n in nodes if n.get("workspace_id") == workspaceId and n.get("node_type") == "list" and n.get("status") == "active" and n.get("name") == listName]
            trace["list"] = {"by": "listName", "value": listName, "candidates": [n.get("id") for n in list_candidates]}
            if len(list_candidates) == 0:
                _log("error", workspaceId, resolution_trace=trace)
                return _err("NOT_FOUND", "No matching active list found for listName in workspace.")
            if len(list_candidates) > 1:
                _log("error", workspaceId, resolution_trace=trace)
                return _err("CONFLICT", "listName is ambiguous within the workspace.", candidates=[n.get("id") for n in list_candidates])
            list_id = list_candidates[0].get("id")
            candidates = [t for t in candidates if t.get("list_node_id") == list_id]
            trace["task"]["candidates_after_list_filter"] = [c.get("id") for c in candidates]

        if len(candidates) == 0:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("NOT_FOUND", "Task not found.")
        if len(candidates) > 1:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("CONFLICT", "taskName is ambiguous; provide listName to disambiguate.", candidates=[c.get("id") for c in candidates])
        task = candidates[0]

    list_node = next((n for n in nodes if n.get("id") == task.get("list_node_id")), None)
    _log("success", task.get("workspace_id"), resolution_trace=trace, http_status=200)
    return {
        "task": {
            "id": task.get("id"),
            "clickupTaskId": task.get("clickup_task_id"),
            "workspaceId": task.get("workspace_id"),
            "listId": task.get("list_node_id"),
            "listName": list_node.get("name") if isinstance(list_node, dict) else None,
            "name": task.get("name"),
            "description": task.get("description"),
            "status": task.get("status_value"),
            "priority": task.get("priority"),
            "dueAt": task.get("due_at"),
            "startAt": task.get("start_at"),
            "closedAt": task.get("closed_at"),
            "assigneeClickupUserIds": task.get("assignee_clickup_user_ids"),
            "tags": task.get("tags"),
            "timeEstimateMs": task.get("time_estimate_ms"),
            "vendorRaw": task.get("vendor_raw"),
            "cacheStatus": task.get("status"),
            "createdAt": task.get("created_at"),
            "updatedAt": task.get("updated_at"),
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_tasks(workspaceId=None, listId=None, listName=None, status=None, dueAfter=None, dueBefore=None, startAfter=None, startBefore=None, createdAfter=None, createdBefore=None, updatedAfter=None, updatedBefore=None, assigneeClickupUserIds=None, tags=None, archived=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        return prefix + secrets.token_hex(8).upper()

    def _log(status_outcome, workspace_id=None, resolution_trace=None, warnings=None, http_status=None, clickup_request=None, clickup_response=None):
        try:
            oplog = _load("operation_log.json")
            entry = {
                "id": _new_id("cu_op_"),
                "workspace_id": workspace_id,
                "tool_name": "get_tasks",
                "bulk_job_id": None,
                "request_params": {
                    "workspaceId": workspaceId,
                    "listId": listId,
                    "listName": listName,
                    "status": status,
                    "dueAfter": dueAfter,
                    "dueBefore": dueBefore,
                    "startAfter": startAfter,
                    "startBefore": startBefore,
                    "createdAfter": createdAfter,
                    "createdBefore": createdBefore,
                    "updatedAfter": updatedAfter,
                    "updatedBefore": updatedBefore,
                    "assigneeClickupUserIds": assigneeClickupUserIds,
                    "tags": tags,
                    "archived": archived,
                    "sortBy": sortBy,
                    "sortOrder": sortOrder,
                    "limit": limit,
                    "cursor": cursor,
                },
                "resolution_trace": resolution_trace,
                "clickup_request": clickup_request,
                "clickup_response": clickup_response,
                "http_status": http_status,
                "warnings": warnings,
                "status": status_outcome,
                "created_at": now,
                "updated_at": now,
            }
            oplog.append(entry)
            _save("operation_log.json", oplog)
        except Exception:
            pass

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string."))
        try:
            ss = s.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string."))

    # Validate inputs
    if workspaceId is not None and (not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId)):
        _log("error", None, resolution_trace={"stage": "validate", "field": "workspaceId"})
        return _err("VALIDATION_ERROR", "Invalid workspaceId format; expected ^cu_wsp_[0-9A-Z]+$.")
    if listId is not None and (not isinstance(listId, str) or not re.match(r"^cu_nod_[0-9A-Z]+$", listId)):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "listId"})
        return _err("VALIDATION_ERROR", "Invalid listId format; expected ^cu_nod_[0-9A-Z]+$.")
    if listName is not None and not isinstance(listName, str):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string.")
    if listId is None and listName is None:
        _log("error", workspaceId, resolution_trace={"stage": "validate"})
        return _err("VALIDATION_ERROR", "Must provide either listId or listName.")
    if status is not None:
        if not isinstance(status, list) or any(not isinstance(x, str) for x in status):
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be an array of strings.")
    if assigneeClickupUserIds is not None:
        if not isinstance(assigneeClickupUserIds, list) or any(not isinstance(x, str) for x in assigneeClickupUserIds):
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "assigneeClickupUserIds"})
            return _err("VALIDATION_ERROR", "assigneeClickupUserIds must be an array of strings.")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "tags"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if archived is not None and not isinstance(archived, bool):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "archived"})
        return _err("VALIDATION_ERROR", "archived must be a boolean.")
    if sortBy is not None and sortBy not in ("created_at", "updated_at", "due_at", "start_at", "priority", "name"):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "sortBy"})
        return _err("VALIDATION_ERROR", "Invalid sortBy.")
    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "sortOrder"})
        return _err("VALIDATION_ERROR", "Invalid sortOrder.")
    if limit is not None:
        if not isinstance(limit, int):
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    # Parse date filters
    filters_dt = {}
    for fld, val in [("dueAfter", dueAfter), ("dueBefore", dueBefore), ("startAfter", startAfter), ("startBefore", startBefore),
                     ("createdAfter", createdAfter), ("createdBefore", createdBefore), ("updatedAfter", updatedAfter), ("updatedBefore", updatedBefore)]:
        parsed = _parse_dt(val, fld)
        if isinstance(parsed, tuple) and parsed and parsed[0] == "__err__":
            _log("error", workspaceId, resolution_trace={"stage": "validate", "field": fld})
            return parsed[1]
        filters_dt[fld] = parsed

    nodes = _load("nodes.json")
    tasks = _load("tasks.json")

    # Resolve list
    trace = {"list": {}, "workspace": {}}
    list_node = None
    if listId is not None:
        list_node = next((n for n in nodes if n.get("id") == listId), None)
        trace["list"] = {"by": "listId", "value": listId}
        if not list_node or list_node.get("status") == "deleted":
            _log("error", workspaceId, resolution_trace=trace)
            return _err("NOT_FOUND", "List not found.")
        if list_node.get("node_type") != "list":
            _log("error", workspaceId, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "listId must reference a node_type='list'.")
        if workspaceId is not None and list_node.get("workspace_id") != workspaceId:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "workspaceId does not match the list's workspace.")
        workspaceId_resolved = list_node.get("workspace_id")
    else:
        if workspaceId is None:
            _log("error", None, resolution_trace={"stage": "resolve", "need": "workspaceId for listName resolution"})
            return _err("VALIDATION_ERROR", "workspaceId is required when resolving listName.")
        trace["workspace"] = {"by": "workspaceId", "value": workspaceId}
        candidates = [n for n in nodes if n.get("workspace_id") == workspaceId and n.get("node_type") == "list" and n.get("status") == "active" and n.get("name") == listName]
        trace["list"] = {"by": "listName", "value": listName, "candidates": [c.get("id") for c in candidates]}
        if len(candidates) == 0:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("NOT_FOUND", "No matching active list found for listName in workspace.")
        if len(candidates) > 1:
            _log("error", workspaceId, resolution_trace=trace)
            return _err("CONFLICT", "listName is ambiguous within the workspace.", candidates=[c.get("id") for c in candidates])
        list_node = candidates[0]
        workspaceId_resolved = workspaceId

    # Filter tasks
    rows = [t for t in tasks if t.get("status") != "deleted" and t.get("list_node_id") == list_node.get("id")]
    # archived flag: tasks schema doesn't have archived; treat archived=True as include all active cache rows; archived=False default.
    # If list node itself archived and archived flag false, still return tasks (vendor semantics vary); keep simple:
    if archived is False or archived is None:
        pass

    if status is not None:
        rows = [t for t in rows if (t.get("status_value") in status)]

    if assigneeClickupUserIds is not None:
        aset = set(assigneeClickupUserIds)
        def _has_any_assignee(t):
            a = t.get("assignee_clickup_user_ids")
            return isinstance(a, list) and any(x in aset for x in a)
        rows = [t for t in rows if _has_any_assignee(t)]

    if tags is not None:
        tset = set(tags)
        def _has_any_tag(t):
            tg = t.get("tags")
            return isinstance(tg, list) and any(x in tset for x in tg)
        rows = [t for t in rows if _has_any_tag(t)]

    def _dt_or_none(v):
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    # Apply date ranges
    da, db = filters_dt["dueAfter"], filters_dt["dueBefore"]
    if da is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("due_at")) is not None and _dt_or_none(t.get("due_at")) > da)]
    if db is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("due_at")) is not None and _dt_or_none(t.get("due_at")) < db)]
    sa, sb = filters_dt["startAfter"], filters_dt["startBefore"]
    if sa is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("start_at")) is not None and _dt_or_none(t.get("start_at")) > sa)]
    if sb is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("start_at")) is not None and _dt_or_none(t.get("start_at")) < sb)]
    ca, cb = filters_dt["createdAfter"], filters_dt["createdBefore"]
    if ca is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("created_at")) is not None and _dt_or_none(t.get("created_at")) > ca)]
    if cb is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("created_at")) is not None and _dt_or_none(t.get("created_at")) < cb)]
    ua, ub = filters_dt["updatedAfter"], filters_dt["updatedBefore"]
    if ua is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("updated_at")) is not None and _dt_or_none(t.get("updated_at")) > ua)]
    if ub is not None:
        rows = [t for t in rows if (_dt_or_none(t.get("updated_at")) is not None and _dt_or_none(t.get("updated_at")) < ub)]

    total = len(rows)

    # Sort
    sb = sortBy or "created_at"
    so = sortOrder or "desc"
    reverse = (so == "desc")

    def _sort_key(t):
        if sb in ("created_at", "updated_at", "due_at", "start_at"):
            dt = _dt_or_none(t.get(sb))
            # None sort last for asc, first for desc
            if dt is None:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            return dt
        if sb == "priority":
            p = t.get("priority")
            if p is None:
                return -1 if reverse else 10
            return p
        if sb == "name":
            return (t.get("name") or "").lower()
        return (t.get("created_at") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination (opaque base64 of start index)
    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", workspaceId_resolved, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("listId") != list_node.get("id"):
                _log("error", workspaceId_resolved, resolution_trace=trace)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start_index = int(payload.get("i", 0))
            if start_index < 0:
                raise ValueError("neg")
        except Exception:
            _log("error", workspaceId_resolved, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
    page_limit = limit if limit is not None else 50
    page = rows[start_index:start_index + page_limit]
    next_i = start_index + len(page)
    has_more = next_i < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "listId": list_node.get("id"), "i": next_i}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    def _task_brief(t):
        return {
            "id": t.get("id"),
            "clickupTaskId": t.get("clickup_task_id"),
            "name": t.get("name"),
            "status": t.get("status_value"),
            "priority": t.get("priority"),
            "dueAt": t.get("due_at"),
            "startAt": t.get("start_at"),
            "assigneeClickupUserIds": t.get("assignee_clickup_user_ids"),
            "tags": t.get("tags"),
            "timeEstimateMs": t.get("time_estimate_ms"),
            "createdAt": t.get("created_at"),
            "updatedAt": t.get("updated_at"),
        }

    _log("success", workspaceId_resolved, resolution_trace=trace, http_status=200)
    return {
        "tasks": [_task_brief(t) for t in page],
        "meta": {
            "workspaceId": workspaceId_resolved,
            "listId": list_node.get("id"),
            "listName": list_node.get("name"),
            "total": total,
            "limit": page_limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000),
            "sortBy": sb,
            "sortOrder": so,
        }
    }

def update_task(workspaceId=None, taskId=None, taskName=None, listName=None, name=None, description=None, status=None, priority=None, dueAt=None, startAt=None, assigneeClickupUserIds=None, tags=None, timeEstimateMs=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # --- helpers ---
    def _log(status_str, workspace_id=None, resolution_trace=None, warnings=None, http_status=None, clickup_request=None, clickup_response=None):
        op = _load("operation_log.json")
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        entry = {
            "id": op_id,
            "workspace_id": workspace_id,
            "tool_name": "update_task",
            "bulk_job_id": None,
            "request_params": {
                "workspaceId": workspaceId,
                "taskId": taskId,
                "taskName": taskName,
                "listName": listName,
                "name": name,
                "description": description,
                "status": status,
                "priority": priority,
                "dueAt": dueAt,
                "startAt": startAt,
                "assigneeClickupUserIds": assigneeClickupUserIds,
                "tags": tags,
                "timeEstimateMs": timeEstimateMs,
            },
            "resolution_trace": resolution_trace,
            "clickup_request": clickup_request,
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings,
            "status": status_str,
            "created_at": now,
            "updated_at": now,
        }
        op.append(entry)
        _save("operation_log.json", op)

    def _is_dt(s):
        if s is None:
            return True
        if not isinstance(s, str):
            return False
        try:
            # accept 'Z' suffix
            s2 = s.replace("Z", "+00:00")
            datetime.datetime.fromisoformat(s2)
            return True
        except Exception:
            return False

    def _resolve_workspace():
        wss = _load("workspaces.json")
        if workspaceId is not None:
            if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
                return None, _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
            ws = next((w for w in wss if w.get("id") == workspaceId and w.get("status") != "deleted"), None)
            if not ws:
                return None, _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)
            return ws, None
        # ambient auth: choose a workspace that can serve (any non-deleted)
        ws = next((w for w in wss if w.get("status") != "deleted"), None)
        if not ws:
            return None, _err("UNAUTHORIZED", "No available workspace context")
        return ws, None

    def _resolve_list_by_name(nodes, ws_id, lname):
        matches = [n for n in nodes
                   if n.get("workspace_id") == ws_id and n.get("node_type") == "list"
                   and n.get("status") != "deleted" and n.get("name") == lname]
        if not matches:
            return None, _err("NOT_FOUND", "List not found", listName=lname)
        if len(matches) > 1:
            return None, _err("CONFLICT", "Ambiguous listName; multiple matching lists in workspace", listName=lname, matches=[m.get("id") for m in matches])
        return matches[0], None

    def _resolve_task(tasks, nodes, ws_id):
        # returns (task_row, trace, error)
        trace = {"workspaceId": ws_id}
        if taskId is not None:
            if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]+$", taskId):
                return None, trace, _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]+$")
            t = next((x for x in tasks if x.get("id") == taskId and x.get("status") != "deleted"), None)
            if not t:
                return None, trace, _err("NOT_FOUND", "Task not found", taskId=taskId)
            if t.get("workspace_id") != ws_id:
                return None, trace, _err("NOT_FOUND", "Task not found in workspace scope", taskId=taskId, workspaceId=ws_id)
            trace["taskId"] = taskId
            trace["resolvedBy"] = "taskId"
            return t, trace, None

        if taskName is None or not isinstance(taskName, str) or taskName.strip() == "":
            return None, trace, _err("VALIDATION_ERROR", "Either taskId or taskName must be provided")

        # optional listName disambiguation
        list_node = None
        if listName is not None:
            if not isinstance(listName, str) or listName.strip() == "":
                return None, trace, _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")
            list_node, e = _resolve_list_by_name(nodes, ws_id, listName)
            if e:
                return None, trace, e
            trace["listName"] = listName
            trace["resolvedListNodeId"] = list_node.get("id")

        candidates = [x for x in tasks if x.get("workspace_id") == ws_id and x.get("status") != "deleted" and x.get("name") == taskName]
        if list_node:
            candidates = [x for x in candidates if x.get("list_node_id") == list_node.get("id")]

        if not candidates:
            return None, trace, _err("NOT_FOUND", "Task not found", taskName=taskName, listName=listName)
        if len(candidates) > 1:
            # require enough scope to disambiguate
            return None, trace, _err("CONFLICT", "Ambiguous taskName; provide listName to disambiguate", taskName=taskName, candidateTaskIds=[c.get("id") for c in candidates])
        t = candidates[0]
        trace["taskName"] = taskName
        trace["resolvedBy"] = "taskName"
        trace["taskId"] = t.get("id")
        return t, trace, None

    # --- validation ---
    ws, e = _resolve_workspace()
    if e:
        _log("error", None)
        return e
    ws_id = ws["id"]

    if taskId is None and taskName is None:
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided")

    update_fields = {
        "name": name,
        "description": description,
        "status": status,
        "priority": priority,
        "dueAt": dueAt,
        "startAt": startAt,
        "assigneeClickupUserIds": assigneeClickupUserIds,
        "tags": tags,
        "timeEstimateMs": timeEstimateMs,
    }
    provided_any = any(v is not None for v in update_fields.values())
    if not provided_any:
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "No update fields provided")

    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "description must be a string")
    if status is not None and (not isinstance(status, str) or status.strip() == ""):
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "status must be a non-empty string")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "priority must be an integer")
        if priority < 1 or priority > 4:
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4")
    if timeEstimateMs is not None:
        if not isinstance(timeEstimateMs, int):
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "timeEstimateMs must be an integer")
        if timeEstimateMs < 0:
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "timeEstimateMs must be >= 0")
    if not _is_dt(dueAt):
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "dueAt must be an RFC3339/ISO-8601 date-time string")
    if not _is_dt(startAt):
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "startAt must be an RFC3339/ISO-8601 date-time string")
    if assigneeClickupUserIds is not None:
        if not isinstance(assigneeClickupUserIds, list) or any(not isinstance(x, str) for x in assigneeClickupUserIds):
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "assigneeClickupUserIds must be an array of strings")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) or x.strip() == "" for x in tags):
            _log("error", ws_id)
            return _err("VALIDATION_ERROR", "tags must be an array of non-empty strings")

    # --- resolve ---
    tasks = _load("tasks.json")
    nodes = _load("nodes.json")

    task_row, trace, e = _resolve_task(tasks, nodes, ws_id)
    if e:
        _log("error", ws_id, resolution_trace=trace)
        return e

    # Validate list node exists and active (FK rule for list_node_id)
    list_node = next((n for n in nodes if n.get("id") == task_row.get("list_node_id") and n.get("node_type") == "list" and n.get("status") != "deleted"), None)
    if not list_node:
        _log("error", ws_id, resolution_trace=trace)
        return _err("CONFLICT", "Task references a missing/deleted list; cannot update", taskId=task_row.get("id"), listNodeId=task_row.get("list_node_id"))

    # Validate status is valid for list (if list has statuses)
    if status is not None:
        md = list_node.get("vendor_metadata") or {}
        statuses = md.get("statuses")
        if isinstance(statuses, list) and statuses:
            allowed = set()
            for s in statuses:
                if isinstance(s, str):
                    allowed.add(s)
                elif isinstance(s, dict) and isinstance(s.get("status"), str):
                    allowed.add(s.get("status"))
                elif isinstance(s, dict) and isinstance(s.get("name"), str):
                    allowed.add(s.get("name"))
            if allowed and status not in allowed:
                _log("error", ws_id, resolution_trace=trace)
                return _err("VALIDATION_ERROR", "Unknown status for destination list", status=status, allowedStatuses=sorted(list(allowed)))

    # --- mutate ---
    changed = False
    for i, x in enumerate(tasks):
        if x.get("id") == task_row.get("id"):
            if name is not None:
                x["name"] = name
                changed = True
            if description is not None:
                x["description"] = description
                changed = True
            if status is not None:
                x["status_value"] = status
                # also closed_at semantics: if status indicates "closed" isn't available; we don't infer.
                changed = True
            if priority is not None:
                x["priority"] = priority
                changed = True
            if dueAt is not None:
                x["due_at"] = dueAt
                changed = True
            if startAt is not None:
                x["start_at"] = startAt
                changed = True
            if assigneeClickupUserIds is not None:
                x["assignee_clickup_user_ids"] = assigneeClickupUserIds
                changed = True
            if tags is not None:
                x["tags"] = tags
                changed = True
            if timeEstimateMs is not None:
                x["time_estimate_ms"] = timeEstimateMs
                changed = True

            if not isinstance(x.get("name"), str) or x["name"].strip() == "":
                _log("error", ws_id, resolution_trace=trace)
                return _err("VALIDATION_ERROR", "Task name cannot be empty")

            x["updated_at"] = now
            task_row = x
            tasks[i] = x
            break

    if not changed:
        # If no fields were actually different, still "no success without effect" — treat as conflict?
        _log("error", ws_id, resolution_trace=trace)
        return _err("CONFLICT", "Update would have no effect (fields identical or not applicable)")

    _save("tasks.json", tasks)
    _log("success", ws_id, resolution_trace=trace)

    return {"task": task_row}

def move_task(workspaceId=None, taskId=None, taskName=None, sourceListName=None, listId=None, listName=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_str, workspace_id=None, resolution_trace=None, warnings=None):
        op = _load("operation_log.json")
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        entry = {
            "id": op_id,
            "workspace_id": workspace_id,
            "tool_name": "move_task",
            "bulk_job_id": None,
            "request_params": {
                "workspaceId": workspaceId,
                "taskId": taskId,
                "taskName": taskName,
                "sourceListName": sourceListName,
                "listId": listId,
                "listName": listName,
            },
            "resolution_trace": resolution_trace,
            "clickup_request": None,
            "clickup_response": None,
            "http_status": None,
            "warnings": warnings,
            "status": status_str,
            "created_at": now,
            "updated_at": now,
        }
        op.append(entry)
        _save("operation_log.json", op)

    def _resolve_workspace():
        wss = _load("workspaces.json")
        if workspaceId is not None:
            if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
                return None, _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
            ws = next((w for w in wss if w.get("id") == workspaceId and w.get("status") != "deleted"), None)
            if not ws:
                return None, _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)
            return ws, None
        ws = next((w for w in wss if w.get("status") != "deleted"), None)
        if not ws:
            return None, _err("UNAUTHORIZED", "No available workspace context")
        return ws, None

    def _resolve_list_by_id(nodes, ws_id, lid):
        if not isinstance(lid, str) or not re.match(r"^cu_nod_[0-9A-Z]+$", lid):
            return None, _err("VALIDATION_ERROR", "listId must match ^cu_nod_[0-9A-Z]+$")
        n = next((x for x in nodes if x.get("id") == lid and x.get("workspace_id") == ws_id and x.get("node_type") == "list" and x.get("status") != "deleted"), None)
        if not n:
            return None, _err("NOT_FOUND", "Destination list not found", listId=lid)
        return n, None

    def _resolve_list_by_name(nodes, ws_id, lname):
        if not isinstance(lname, str) or lname.strip() == "":
            return None, _err("VALIDATION_ERROR", "listName must be a non-empty string")
        matches = [n for n in nodes
                   if n.get("workspace_id") == ws_id and n.get("node_type") == "list"
                   and n.get("status") != "deleted" and n.get("name") == lname]
        if not matches:
            return None, _err("NOT_FOUND", "Destination list not found", listName=lname)
        if len(matches) > 1:
            return None, _err("CONFLICT", "Ambiguous listName; multiple matching destination lists in workspace", listName=lname, matches=[m.get("id") for m in matches])
        return matches[0], None

    def _resolve_source_list(nodes, ws_id, lname):
        if not isinstance(lname, str) or lname.strip() == "":
            return None, _err("VALIDATION_ERROR", "sourceListName must be a non-empty string")
        matches = [n for n in nodes
                   if n.get("workspace_id") == ws_id and n.get("node_type") == "list"
                   and n.get("status") != "deleted" and n.get("name") == lname]
        if not matches:
            return None, _err("NOT_FOUND", "Source list not found", sourceListName=lname)
        if len(matches) > 1:
            return None, _err("CONFLICT", "Ambiguous sourceListName; multiple matching source lists in workspace", sourceListName=lname, matches=[m.get("id") for m in matches])
        return matches[0], None

    ws, e = _resolve_workspace()
    if e:
        _log("error", None)
        return e
    ws_id = ws["id"]

    if taskId is None and taskName is None:
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "Either taskId or (taskName + sourceListName) must be provided")

    if listId is None and listName is None:
        _log("error", ws_id)
        return _err("VALIDATION_ERROR", "Destination listId or listName is required")

    nodes = _load("nodes.json")
    tasks = _load("tasks.json")

    trace = {"workspaceId": ws_id}

    # destination list
    if listId is not None and listName is not None:
        _log("error", ws_id, resolution_trace=trace)
        return _err("VALIDATION_ERROR", "Provide only one of listId or listName")

    if listId is not None:
        dest_list, e = _resolve_list_by_id(nodes, ws_id, listId)
        if e:
            _log("error", ws_id, resolution_trace=trace)
            return e
        trace["destination"] = {"listId": listId, "resolvedListNodeId": dest_list.get("id")}
    else:
        dest_list, e = _resolve_list_by_name(nodes, ws_id, listName)
        if e:
            _log("error", ws_id, resolution_trace=trace)
            return e
        trace["destination"] = {"listName": listName, "resolvedListNodeId": dest_list.get("id")}

    # resolve task
    task_row = None
    if taskId is not None:
        if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]+$", taskId):
            _log("error", ws_id, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]+$")
        task_row = next((t for t in tasks if t.get("id") == taskId and t.get("status") != "deleted" and t.get("workspace_id") == ws_id), None)
        if not task_row:
            _log("error", ws_id, resolution_trace=trace)
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
        trace["source"] = {"resolvedBy": "taskId", "taskId": taskId}
    else:
        if not isinstance(taskName, str) or taskName.strip() == "":
            _log("error", ws_id, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "taskName must be a non-empty string")
        if sourceListName is None:
            _log("error", ws_id, resolution_trace=trace)
            return _err("VALIDATION_ERROR", "sourceListName is required when resolving by taskName for moving")
        src_list, e = _resolve_source_list(nodes, ws_id, sourceListName)
        if e:
            _log("error", ws_id, resolution_trace=trace)
            return e
        trace["source"] = {"resolvedBy": "taskName", "taskName": taskName, "sourceListName": sourceListName, "resolvedSourceListNodeId": src_list.get("id")}
        candidates = [t for t in tasks if t.get("workspace_id") == ws_id and t.get("status") != "deleted" and t.get("name") == taskName and t.get("list_node_id") == src_list.get("id")]
        if not candidates:
            _log("error", ws_id, resolution_trace=trace)
            return _err("NOT_FOUND", "Task not found in source list", taskName=taskName, sourceListName=sourceListName)
        if len(candidates) > 1:
            _log("error", ws_id, resolution_trace=trace)
            return _err("CONFLICT", "Ambiguous taskName in source list", taskName=taskName, sourceListName=sourceListName, candidateTaskIds=[c.get("id") for c in candidates])
        task_row = candidates[0]

    if task_row.get("list_node_id") == dest_list.get("id"):
        _log("error", ws_id, resolution_trace=trace)
        return _err("CONFLICT", "Task is already in the destination list", taskId=task_row.get("id"), listId=dest_list.get("id"))

    # warning if statuses differ
    warnings = []
    src_list_node = next((n for n in nodes if n.get("id") == task_row.get("list_node_id")), None)
    src_statuses = None
    dest_statuses = None
    if src_list_node:
        src_md = src_list_node.get("vendor_metadata") or {}
        src_statuses = src_md.get("statuses")
    dest_md = dest_list.get("vendor_metadata") or {}
    dest_statuses = dest_md.get("statuses")

    reset_status = False
    if isinstance(src_statuses, list) and isinstance(dest_statuses, list):
        def _norm_statuses(arr):
            out = set()
            for s in arr:
                if isinstance(s, str):
                    out.add(s)
                elif isinstance(s, dict) and isinstance(s.get("status"), str):
                    out.add(s.get("status"))
                elif isinstance(s, dict) and isinstance(s.get("name"), str):
                    out.add(s.get("name"))
            return out
        if _norm_statuses(src_statuses) != _norm_statuses(dest_statuses):
            reset_status = True
            warnings.append("Destination list has different status options; task status_value was reset to null.")

    # mutate
    updated_task = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_row.get("id"):
            t["list_node_id"] = dest_list.get("id")
            if reset_status:
                t["status_value"] = None
            t["updated_at"] = now
            tasks[i] = t
            updated_task = t
            break

    if not updated_task:
        _log("error", ws_id, resolution_trace=trace)
        return _err("NOT_FOUND", "Task not found")

    _save("tasks.json", tasks)
    _log("success", ws_id, resolution_trace=trace, warnings=warnings if warnings else None)
    return {"task": updated_task, "warnings": warnings}

def duplicate_task(workspaceId=None, taskId=None, taskName=None, sourceListName=None, listId=None, listName=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    workspaces = _load("workspaces.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")

    resolution_trace = {}
    warnings = []

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "duplicate_task",
            "bulk_job_id": None,
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "sourceListName": sourceListName, "listId": listId, "listName": listName},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/task/{task_id}/duplicate", "method": "POST", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    ws_row = None
    if workspaceId is not None:
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            _log("error", None, 400, {"error": "invalid_workspaceId"})
            return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$.", field="workspaceId")
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
        if not ws_row or ws_row.get("status") == "deleted":
            _log("error", workspaceId, 404, {"error": "workspace_not_found"})
            return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    # Resolve source task
    src_task = None
    if taskId is not None:
        if not isinstance(taskId, str) or not taskId.strip():
            _log("error", workspaceId, 400, {"error": "invalid_taskId"})
            return _err("VALIDATION_ERROR", "taskId must be a non-empty string.", field="taskId")
        # Accept local id or any string id; look up by local id first then clickup_task_id
        src_task = next((t for t in tasks_store if isinstance(t, dict) and t.get("id") == taskId and t.get("status") != "deleted"), None)
        if src_task is None:
            src_task = next((t for t in tasks_store if isinstance(t, dict) and t.get("clickup_task_id") == taskId and t.get("status") != "deleted"), None)
        if not src_task:
            _log("error", workspaceId, 404, {"error": "task_not_found"})
            return _err("NOT_FOUND", "Task not found.", taskId=taskId)
        resolution_trace["taskId->source"] = {"id": src_task.get("id"), "clickup_task_id": src_task.get("clickup_task_id")}
    else:
        if not isinstance(taskName, str) or not taskName.strip():
            _log("error", workspaceId, 400, {"error": "missing_taskName"})
            return _err("VALIDATION_ERROR", "taskName is required when taskId is not provided.", field="taskName")
        if not isinstance(sourceListName, str) or not sourceListName.strip():
            _log("error", workspaceId, 400, {"error": "missing_sourceListName"})
            return _err("VALIDATION_ERROR", "sourceListName is required when resolving by taskName.", field="sourceListName")
        if workspaceId is None:
            _log("error", None, 400, {"error": "missing_workspace_for_name_resolution"})
            return _err("VALIDATION_ERROR", "workspaceId is required for name-based resolution.", field="workspaceId")

        # Resolve source list by name (must be unique)
        src_list_candidates = [n for n in nodes if isinstance(n, dict) and n.get("workspace_id") == workspaceId and n.get("node_type") == "list" and n.get("status") != "deleted" and (n.get("name") or "").strip() == sourceListName.strip()]
        if len(src_list_candidates) == 0:
            _log("error", workspaceId, 404, {"error": "source_list_not_found"})
            return _err("NOT_FOUND", "Source list not found.", sourceListName=sourceListName)
        if len(src_list_candidates) > 1:
            _log("error", workspaceId, 409, {"error": "ambiguous_sourceListName"})
            return _err("CONFLICT", "Ambiguous sourceListName; provide source listId via taskId flow.", sourceListName=sourceListName, matches=[x.get("id") for x in src_list_candidates])
        src_list = src_list_candidates[0]
        resolution_trace["sourceListName->listId"] = {"sourceListName": sourceListName, "id": src_list.get("id")}

        task_candidates = [t for t in tasks_store if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") == workspaceId and t.get("list_node_id") == src_list.get("id") and (t.get("name") or "").strip() == taskName.strip()]
        if len(task_candidates) == 0:
            _log("error", workspaceId, 404, {"error": "task_not_found_by_name"})
            return _err("NOT_FOUND", "Task not found.", taskName=taskName, sourceListName=sourceListName)
        if len(task_candidates) > 1:
            _log("error", workspaceId, 409, {"error": "ambiguous_taskName"})
            return _err("CONFLICT", "Ambiguous taskName within sourceListName.", taskName=taskName, sourceListName=sourceListName, matches=[x.get("id") for x in task_candidates])
        src_task = task_candidates[0]
        resolution_trace["taskName->taskId"] = {"taskName": taskName, "id": src_task.get("id")}

    if ws_row is not None and src_task.get("workspace_id") != workspaceId:
        _log("error", workspaceId, 409, {"error": "workspace_task_mismatch"})
        return _err("CONFLICT", "Task does not belong to workspaceId.", workspaceId=workspaceId, taskId=src_task.get("id"))

    # Resolve destination list (optional)
    dest_list = None
    if listId is None and listName is None:
        dest_list = next((n for n in nodes if isinstance(n, dict) and n.get("id") == src_task.get("list_node_id") and n.get("node_type") == "list" and n.get("status") != "deleted"), None)
        if not dest_list:
            _log("error", src_task.get("workspace_id"), 409, {"error": "source_list_deleted"})
            return _err("CONFLICT", "Source list is deleted; provide a valid destination list.", sourceListId=src_task.get("list_node_id"))
    else:
        # destination list resolution: accept local id or vendor clickup_node_id
        if listId is not None:
            if not isinstance(listId, str) or not listId.strip():
                _log("error", src_task.get("workspace_id"), 400, {"error": "invalid_listId"})
                return _err("VALIDATION_ERROR", "listId must be a non-empty string.", field="listId")
            s = listId.strip()
            if re.match(r"^cu_nod_[0-9A-Z]+$", s):
                dest_list = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"), None)
            else:
                candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"]
                if workspaceId is not None:
                    candidates = [n for n in candidates if n.get("workspace_id") == workspaceId]
                if len(candidates) == 1:
                    dest_list = candidates[0]
                    resolution_trace["listId(vendor)->listNodeId"] = {"clickup_node_id": s, "id": dest_list.get("id")}
                elif len(candidates) > 1:
                    _log("error", workspaceId, 409, {"error": "ambiguous_listId_vendor"})
                    return _err("CONFLICT", "Ambiguous listId (vendor id) matched multiple lists in scope.", listId=s, matches=[c.get("id") for c in candidates])
            if not dest_list:
                _log("error", workspaceId or src_task.get("workspace_id"), 404, {"error": "dest_list_not_found"})
                return _err("NOT_FOUND", "Destination list not found.", listId=listId)
        else:
            if not isinstance(listName, str) or not listName.strip():
                _log("error", workspaceId or src_task.get("workspace_id"), 400, {"error": "invalid_listName"})
                return _err("VALIDATION_ERROR", "listName must be a non-empty string.", field="listName")
            if workspaceId is None:
                # use source workspace for resolution if not provided
                workspace_scope = src_task.get("workspace_id")
            else:
                workspace_scope = workspaceId
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("workspace_id") == workspace_scope and n.get("node_type") == "list" and n.get("status") != "deleted" and (n.get("name") or "").strip() == listName.strip()]
            if len(candidates) == 0:
                _log("error", workspace_scope, 404, {"error": "dest_list_not_found_by_name"})
                return _err("NOT_FOUND", "Destination list not found.", listName=listName)
            if len(candidates) > 1:
                _log("error", workspace_scope, 409, {"error": "ambiguous_dest_listName"})
                return _err("CONFLICT", "Ambiguous listName; provide listId to disambiguate.", listName=listName, matches=[c.get("id") for c in candidates])
            dest_list = candidates[0]
            resolution_trace["listName->listId"] = {"listName": listName, "id": dest_list.get("id")}

        if dest_list.get("workspace_id") != src_task.get("workspace_id"):
            # cross-workspace move not supported by schema here
            _log("error", workspaceId or src_task.get("workspace_id"), 409, {"error": "cross_workspace_duplicate"})
            return _err("CONFLICT", "Destination list must be within the same workspace as the source task.", sourceWorkspaceId=src_task.get("workspace_id"), destWorkspaceId=dest_list.get("workspace_id"))

    # Perform duplication (copy fields)
    new_task_id = _new_id("cu_tsk_", tasks_store)
    clickup_task_id = f"ctk_{_new_id('', [{'id':'X'}])[0:16].lower()}"

    new_row = {
        "id": new_task_id,
        "workspace_id": src_task.get("workspace_id"),
        "list_node_id": dest_list.get("id"),
        "clickup_task_id": clickup_task_id,
        "name": src_task.get("name"),
        "description": src_task.get("description"),
        "status_value": src_task.get("status_value"),
        "priority": src_task.get("priority"),
        "due_at": src_task.get("due_at"),
        "start_at": src_task.get("start_at"),
        "closed_at": src_task.get("closed_at"),
        "assignee_clickup_user_ids": src_task.get("assignee_clickup_user_ids"),
        "tags": src_task.get("tags"),
        "time_estimate_ms": src_task.get("time_estimate_ms"),
        "vendor_raw": src_task.get("vendor_raw"),
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    tasks_store.append(new_row)
    _save("tasks.json", tasks_store)

    resolution_trace["source"] = {"task_id": src_task.get("id"), "list_node_id": src_task.get("list_node_id")}
    resolution_trace["destination"] = {"list_node_id": dest_list.get("id")}

    _log("success", src_task.get("workspace_id"), 200, {"id": clickup_task_id})
    return {"task": new_row, "warnings": warnings or None, "resolution_trace": resolution_trace or None}

def delete_task(workspaceId=None, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    workspaces = _load("workspaces.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")

    resolution_trace = {}
    warnings = []

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "delete_task",
            "bulk_job_id": None,
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/task/{task_id}", "method": "DELETE", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    ws_row = None
    if workspaceId is not None:
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            _log("error", None, 400, {"error": "invalid_workspaceId"})
            return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$.", field="workspaceId")
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
        if not ws_row or ws_row.get("status") == "deleted":
            _log("error", workspaceId, 404, {"error": "workspace_not_found"})
            return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    if taskId is None and taskName is None:
        _log("error", workspaceId, 400, {"error": "missing_identifier"})
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided.", fields=["taskId", "taskName"])

    target = None
    if taskId is not None:
        if not isinstance(taskId, str) or not taskId.strip():
            _log("error", workspaceId, 400, {"error": "invalid_taskId"})
            return _err("VALIDATION_ERROR", "taskId must be a non-empty string.", field="taskId")
        # Accept local task id OR clickup_task_id
        target = next((t for t in tasks_store if isinstance(t, dict) and t.get("id") == taskId), None)
        if target is None:
            target = next((t for t in tasks_store if isinstance(t, dict) and t.get("clickup_task_id") == taskId), None)
        if not target:
            _log("error", workspaceId, 404, {"error": "task_not_found"})
            return _err("NOT_FOUND", "Task not found.", taskId=taskId)
        if ws_row is not None and target.get("workspace_id") != workspaceId:
            _log("error", workspaceId, 409, {"error": "workspace_task_mismatch"})
            return _err("CONFLICT", "Task does not belong to workspaceId.", workspaceId=workspaceId, taskId=target.get("id"))
        resolution_trace["taskId->task"] = {"id": target.get("id"), "clickup_task_id": target.get("clickup_task_id")}
    else:
        if not isinstance(taskName, str) or not taskName.strip():
            _log("error", workspaceId, 400, {"error": "invalid_taskName"})
            return _err("VALIDATION_ERROR", "taskName must be a non-empty string.", field="taskName")

        if workspaceId is None:
            _log("error", None, 400, {"error": "missing_workspace_for_name_resolution"})
            return _err("VALIDATION_ERROR", "workspaceId is required for name-based resolution.", field="workspaceId")

        # If listName provided, resolve list uniquely within workspace
        list_node_id = None
        if listName is not None:
            if not isinstance(listName, str) or not listName.strip():
                _log("error", workspaceId, 400, {"error": "invalid_listName"})
                return _err("VALIDATION_ERROR", "listName must be a non-empty string.", field="listName")
            list_candidates = [n for n in nodes if isinstance(n, dict) and n.get("workspace_id") == workspaceId and n.get("node_type") == "list" and n.get("status") != "deleted" and (n.get("name") or "").strip() == listName.strip()]
            if len(list_candidates) == 0:
                _log("error", workspaceId, 404, {"error": "list_not_found"})
                return _err("NOT_FOUND", "List not found.", listName=listName)
            if len(list_candidates) > 1:
                _log("error", workspaceId, 409, {"error": "ambiguous_listName"})
                return _err("CONFLICT", "Ambiguous listName; provide taskId or a more specific identifier.", listName=listName, matches=[x.get("id") for x in list_candidates])
            list_node_id = list_candidates[0].get("id")
            resolution_trace["listName->listId"] = {"listName": listName, "id": list_node_id}

        candidates = [t for t in tasks_store if isinstance(t, dict) and t.get("workspace_id") == workspaceId and t.get("status") != "deleted" and (t.get("name") or "").strip() == taskName.strip()]
        if list_node_id is not None:
            candidates = [t for t in candidates if t.get("list_node_id") == list_node_id]

        if len(candidates) == 0:
            _log("error", workspaceId, 404, {"error": "task_not_found_by_name"})
            return _err("NOT_FOUND", "Task not found.", taskName=taskName, listName=listName)
        if len(candidates) > 1:
            # business rule: must disambiguate with listName; if still multiple, error
            _log("error", workspaceId, 409, {"error": "ambiguous_taskName"})
            return _err("CONFLICT", "Ambiguous taskName; provide taskId or listName to disambiguate.", taskName=taskName, matches=[x.get("id") for x in candidates])
        target = candidates[0]
        resolution_trace["taskName->taskId"] = {"taskName": taskName, "id": target.get("id")}

    # Permanent delete: lifecycle transition active->deleted only; idempotent if already deleted
    if target.get("status") == "deleted":
        # idempotent "already deleted" treated as success
        _log("success", target.get("workspace_id"), 200, {"deleted": True, "already_deleted": True})
        return {"task": target, "deleted": True, "already_deleted": True}

    # apply transition
    target["status"] = "deleted"
    target["updated_at"] = now
    _save("tasks.json", tasks_store)

    _log("success", target.get("workspace_id"), 200, {"deleted": True})
    return {"task": target, "deleted": True}

def create_bulk_tasks(tasks, listId=None, listName=None, batchSize=None, concurrency=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    bulk_jobs = _load("bulk_jobs.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")

    resolution_trace = {}
    warnings = []

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string.", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss.replace("Z", "+00:00"))
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time.", field=field)

    def _log(outcome, workspace_id=None, bulk_job_id=None, http_status=None, clickup_response=None, per_item=False):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "create_bulk_tasks",
            "bulk_job_id": bulk_job_id,
            "request_params": {"listId": listId, "listName": listName, "batchSize": batchSize, "concurrency": concurrency, "tasks_count": (len(tasks) if isinstance(tasks, list) else None), "per_item": per_item},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/list/{list_id}/task/bulk", "method": "POST", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    # Validate batch/concurrency per schema constraints
    if batchSize is not None:
        if not isinstance(batchSize, int):
            _log("error", None, None, 400, {"error": "invalid_batchSize"})
            return _err("VALIDATION_ERROR", "batchSize must be an integer.", field="batchSize")
        if batchSize < 1 or batchSize > 500:
            _log("error", None, None, 400, {"error": "batchSize_range"})
            return _err("VALIDATION_ERROR", "batchSize must be between 1 and 500.", field="batchSize")
    if concurrency is not None:
        if not isinstance(concurrency, int):
            _log("error", None, None, 400, {"error": "invalid_concurrency"})
            return _err("VALIDATION_ERROR", "concurrency must be an integer.", field="concurrency")
        if concurrency < 1 or concurrency > 50:
            _log("error", None, None, 400, {"error": "concurrency_range"})
            return _err("VALIDATION_ERROR", "concurrency must be between 1 and 50.", field="concurrency")

    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("error", None, None, 400, {"error": "invalid_tasks"})
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array.", field="tasks")
    for i, item in enumerate(tasks):
        if not isinstance(item, dict):
            _log("error", None, None, 400, {"error": "invalid_task_item", "index": i})
            return _err("VALIDATION_ERROR", "Each task must be an object.", index=i)
        if "name" not in item or not isinstance(item.get("name"), str) or not item.get("name").strip():
            _log("error", None, None, 400, {"error": "missing_task_name", "index": i})
            return _err("VALIDATION_ERROR", "Each task must include a non-empty name.", index=i, field="tasks[].name")

    if listId is None and listName is None:
        _log("error", None, None, 400, {"error": "missing_list"})
        return _err("VALIDATION_ERROR", "Either listId or listName must be provided.", fields=["listId", "listName"])

    # Resolve destination list (accept local node id or vendor clickup_node_id); listName requires uniqueness across all workspaces (best effort)
    dest_list = None
    if listId is not None:
        if not isinstance(listId, str) or not listId.strip():
            _log("error", None, None, 400, {"error": "invalid_listId"})
            return _err("VALIDATION_ERROR", "listId must be a non-empty string.", field="listId")
        s = listId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            dest_list = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"), None)
        else:
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "list" and n.get("status") != "deleted"]
            if len(candidates) == 1:
                dest_list = candidates[0]
                resolution_trace["listId(vendor)->listNodeId"] = {"clickup_node_id": s, "id": dest_list.get("id")}
            elif len(candidates) > 1:
                _log("error", None, None, 409, {"error": "ambiguous_listId_vendor"})
                return _err("CONFLICT", "Ambiguous listId (vendor id) matched multiple lists; provide local listId.", listId=s, matches=[c.get("id") for c in candidates])
        if not dest_list:
            _log("error", None, None, 404, {"error": "list_not_found"})
            return _err("NOT_FOUND", "List not found.", listId=listId)
    else:
        if not isinstance(listName, str) or not listName.strip():
            _log("error", None, None, 400, {"error": "invalid_listName"})
            return _err("VALIDATION_ERROR", "listName must be a non-empty string.", field="listName")
        candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "list" and n.get("status") != "deleted" and (n.get("name") or "").strip() == listName.strip()]
        if len(candidates) == 0:
            _log("error", None, None, 404, {"error": "list_not_found_by_name"})
            return _err("NOT_FOUND", "List not found.", listName=listName)
        if len(candidates) > 1:
            _log("error", None, None, 409, {"error": "ambiguous_listName"})
            return _err("CONFLICT", "Ambiguous listName; provide listId to disambiguate.", listName=listName, matches=[c.get("id") for c in candidates])
        dest_list = candidates[0]
        resolution_trace["listName->listId"] = {"listName": listName, "id": dest_list.get("id")}

    workspace_id = dest_list.get("workspace_id")

    # Create bulk job record
    bj_id = _new_id("cu_bjk_", bulk_jobs)
    job = {
        "id": bj_id,
        "workspace_id": workspace_id,
        "job_type": "create_bulk_tasks",
        "target_list_node_id": dest_list.get("id"),
        "batch_size": batchSize,
        "concurrency": concurrency,
        "input_items": tasks,
        "result_summary": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    bulk_jobs.append(job)
    _save("bulk_jobs.json", bulk_jobs)

    # Execute synchronously with simple batching; at-least-once semantics + idempotency per item isn't meaningful for create without ids,
    # so we treat items as processed once within this call.
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("bulk_jobs.json", bulk_jobs)

    succeeded = 0
    failed = 0
    errors_by_type = {}
    created_task_ids = []

    bs = batchSize or 100
    for base in range(0, len(tasks), bs):
        batch = tasks[base:base+bs]
        batch_outcomes = []
        for idx_in_batch, item in enumerate(batch):
            try:
                # Validate item fields
                nm = item.get("name")
                desc = item.get("description")
                st = item.get("status")
                pr = item.get("priority")
                due_norm = _parse_dt(item.get("dueAt"), "dueAt")
                if isinstance(due_norm, dict) and due_norm.get("error"):
                    raise ValueError(due_norm["error"]["message"])
                start_norm = _parse_dt(item.get("startAt"), "startAt")
                if isinstance(start_norm, dict) and start_norm.get("error"):
                    raise ValueError(start_norm["error"]["message"])
                assignees = item.get("assigneeClickupUserIds")
                if assignees is not None and (not isinstance(assignees, list) or any(not isinstance(x, str) for x in assignees)):
                    raise ValueError("assigneeClickupUserIds must be an array of strings")
                tg = item.get("tags")
                if tg is not None and (not isinstance(tg, list) or any(not isinstance(x, str) for x in tg)):
                    raise ValueError("tags must be an array of strings")
                te = item.get("timeEstimateMs")
                if te is not None:
                    if not isinstance(te, int) or te < 0:
                        raise ValueError("timeEstimateMs must be an integer >= 0")
                if pr is not None:
                    if not isinstance(pr, int) or pr < 1 or pr > 4:
                        raise ValueError("priority must be between 1 and 4")

                new_task_id = _new_id("cu_tsk_", tasks_store)
                clickup_task_id = f"ctk_{_new_id('', [{'id':'X'}])[0:16].lower()}"
                row = {
                    "id": new_task_id,
                    "workspace_id": workspace_id,
                    "list_node_id": dest_list.get("id"),
                    "clickup_task_id": clickup_task_id,
                    "name": nm.strip(),
                    "description": desc if desc is None else desc,
                    "status_value": st if st is None else st,
                    "priority": pr,
                    "due_at": due_norm,
                    "start_at": start_norm,
                    "closed_at": None,
                    "assignee_clickup_user_ids": assignees if assignees is not None else None,
                    "tags": tg if tg is not None else None,
                    "time_estimate_ms": te,
                    "vendor_raw": None,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                }
                tasks_store.append(row)
                created_task_ids.append(new_task_id)
                succeeded += 1
                batch_outcomes.append({"index": base + idx_in_batch, "status": "success", "taskId": new_task_id})
            except Exception as e:
                failed += 1
                et = "item_validation_error"
                errors_by_type[et] = errors_by_type.get(et, 0) + 1
                batch_outcomes.append({"index": base + idx_in_batch, "status": "error", "error": str(e)})

        # per-batch log entry
        resolution_trace["last_batch"] = {"start_index": base, "count": len(batch)}
        _log("success", workspace_id, bj_id, 200, {"batch_outcomes": batch_outcomes}, per_item=False)

    _save("tasks.json", tasks_store)

    job["status"] = "completed" if failed == 0 else "failed"
    job["finished_at"] = now
    job["result_summary"] = {"succeeded": succeeded, "failed": failed, "errors_by_type": errors_by_type, "created_task_ids": created_task_ids}
    job["updated_at"] = now
    _save("bulk_jobs.json", bulk_jobs)

    # final log entry
    _log("success" if failed == 0 else "error", workspace_id, bj_id, 200, {"result_summary": job["result_summary"], "job_status": job["status"]}, per_item=False)

    return {"bulk_job": job, "result_summary": job["result_summary"], "warnings": warnings or None, "resolution_trace": resolution_trace or None}

def move_bulk_tasks(tasks, targetListId=None, targetListName=None, batchSize=None, concurrency=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    op_log = _load("operation_log.json")
    bulk_jobs = _load("bulk_jobs.json")
    workspaces = _load("workspaces.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")

    def _log(status, workspace_id=None, bulk_job_id=None, warnings=None, resolution_trace=None, http_status=None, clickup_request=None, clickup_response=None, request_params=None):
        entry = {
            "id": "op_" + uuid.uuid4().hex.upper(),
            "workspace_id": workspace_id,
            "tool_name": "move_bulk_tasks",
            "bulk_job_id": bulk_job_id,
            "request_params": request_params if request_params is not None else {"targetListId": targetListId, "targetListName": targetListName, "tasks": tasks, "batchSize": batchSize, "concurrency": concurrency},
            "resolution_trace": resolution_trace,
            "clickup_request": clickup_request,
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if not isinstance(tasks, list):
        _log("error")
        return _err("VALIDATION_ERROR", "tasks must be an array")
    if len(tasks) < 1:
        _log("error")
        return _err("VALIDATION_ERROR", "tasks must contain at least 1 item")

    if batchSize is not None:
        if not isinstance(batchSize, int):
            _log("error")
            return _err("VALIDATION_ERROR", "batchSize must be an integer")
        if batchSize < 1 or batchSize > 500:
            _log("error")
            return _err("VALIDATION_ERROR", "batchSize must be between 1 and 500")
    if concurrency is not None:
        if not isinstance(concurrency, int):
            _log("error")
            return _err("VALIDATION_ERROR", "concurrency must be an integer")
        if concurrency < 1 or concurrency > 50:
            _log("error")
            return _err("VALIDATION_ERROR", "concurrency must be between 1 and 50")

    # Require destination list
    if targetListId is None and (targetListName is None or (isinstance(targetListName, str) and targetListName.strip() == "")):
        _log("error")
        return _err("VALIDATION_ERROR", "You must provide either targetListId or targetListName to specify the destination list")

    ws_by_id = {w.get("id"): w for w in workspaces}

    # Resolve target list
    resolution_trace = {}
    target_list = None
    if targetListId is not None:
        if not isinstance(targetListId, str) or not re.match(r"^cu_nod_[0-9A-Z]+$", targetListId):
            _log("error")
            return _err("VALIDATION_ERROR", "targetListId must match pattern ^cu_nod_[0-9A-Z]+$")
        target_list = next((n for n in nodes if n.get("id") == targetListId and n.get("status") != "deleted"), None)
        if not target_list:
            _log("error")
            return _err("NOT_FOUND", "Destination list not found", targetListId=targetListId)
        if target_list.get("node_type") != "list":
            _log("error")
            return _err("VALIDATION_ERROR", "targetListId must refer to a node_type='list'")
        resolution_trace["targetList"] = {"by": "targetListId", "targetListId": targetListId}
    else:
        if not isinstance(targetListName, str) or targetListName.strip() == "":
            _log("error")
            return _err("VALIDATION_ERROR", "targetListName must be a non-empty string")
        candidates = [n for n in nodes if n.get("node_type") == "list" and n.get("status") != "deleted" and n.get("name") == targetListName]
        candidates = [n for n in candidates if ws_by_id.get(n.get("workspace_id"), {}).get("status") in ("active", "archived")]
        by_ws = {}
        for n in candidates:
            by_ws.setdefault(n.get("workspace_id"), []).append(n)
        chosen = None
        chosen_ws = None
        for wsid, ns in by_ws.items():
            if len(ns) == 1:
                w = ws_by_id.get(wsid)
                if not w:
                    continue
                if chosen is None:
                    chosen = ns[0]
                    chosen_ws = w
                else:
                    if chosen_ws and chosen_ws.get("status") != "active" and w.get("status") == "active":
                        chosen = ns[0]
                        chosen_ws = w
                    elif chosen_ws and chosen_ws.get("status") == w.get("status"):
                        chosen = "AMBIG"
        if chosen == "AMBIG" or chosen is None:
            _log("error", resolution_trace={"targetList": {"by": "targetListName", "targetListName": targetListName, "matches_by_workspace": {k: [x.get("id") for x in v] for k, v in by_ws.items()}}})
            return _err("CONFLICT", "Ambiguous or unresolved targetListName; provide targetListId or more scope", targetListName=targetListName)
        target_list = chosen
        resolution_trace["targetList"] = {"by": "targetListName", "targetListName": targetListName, "targetListId": target_list.get("id"), "workspaceId": target_list.get("workspace_id")}

    dest_workspace_id = target_list.get("workspace_id")
    dest_ws = ws_by_id.get(dest_workspace_id)
    if not dest_ws or dest_ws.get("status") == "deleted":
        _log("error", workspace_id=dest_workspace_id, resolution_trace=resolution_trace)
        return _err("UNAUTHORIZED", "No accessible workspace found for destination list")

    # Create bulk job record
    bulk_job_id = "cu_bj_" + uuid.uuid4().hex.upper()
    job = {
        "id": bulk_job_id,
        "workspace_id": dest_workspace_id,
        "job_type": "move_bulk_tasks",
        "target_list_node_id": target_list.get("id"),
        "batch_size": batchSize,
        "concurrency": concurrency,
        "input_items": tasks,
        "result_summary": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    bulk_jobs.append(job)
    _save("bulk_jobs.json", bulk_jobs)

    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("bulk_jobs.json", bulk_jobs)

    tasks_by_id = {t.get("id"): t for t in tasks_store}

    # For listName resolution of source list, scope-aware but tool doesn't provide workspace;
    # if ambiguous across workspaces => conflict.
    nodes_by_name = {}
    for n in nodes:
        if n.get("status") == "deleted" or n.get("node_type") != "list":
            continue
        nodes_by_name.setdefault(n.get("name"), []).append(n)

    def _resolve_list_by_name_scoped(list_name):
        cands = [n for n in nodes_by_name.get(list_name, []) if ws_by_id.get(n.get("workspace_id"), {}).get("status") in ("active", "archived")]
        by_ws = {}
        for n in cands:
            by_ws.setdefault(n.get("workspace_id"), []).append(n)
        if len(cands) == 0:
            return None, {"listName": list_name, "matches": []}, "NOT_FOUND"
        if len(by_ws) > 1:
            return None, {"listName": list_name, "matches_by_workspace": {k: [x.get("id") for x in v] for k, v in by_ws.items()}}, "CONFLICT"
        if len(cands) > 1:
            return None, {"listName": list_name, "matches": [x.get("id") for x in cands]}, "CONFLICT"
        return cands[0], {"listName": list_name, "listId": cands[0].get("id"), "workspaceId": cands[0].get("workspace_id")}, None

    # Idempotency: if already processed successfully for this bulk job, skip
    done_task_ids = set()
    for o in op_log:
        if o.get("bulk_job_id") == bulk_job_id and o.get("tool_name") == "move_bulk_tasks" and o.get("status") == "success":
            rt = o.get("resolution_trace") or {}
            tid = rt.get("taskId")
            if isinstance(tid, str):
                done_task_ids.add(tid)

    dest_statuses = (target_list.get("vendor_metadata") or {}).get("statuses")
    succeeded = 0
    failed = 0
    errors_by_type = {}
    per_item = []
    warnings_accum = []

    for idx, it in enumerate(tasks):
        item_params = {"targetListId": targetListId, "targetListName": targetListName, "tasks": [it], "batchSize": batchSize, "concurrency": concurrency}
        if not isinstance(it, dict):
            failed += 1
            errors_by_type["VALIDATION_ERROR"] = errors_by_type.get("VALIDATION_ERROR", 0) + 1
            msg = "task item must be an object"
            per_item.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": msg}})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace={"item_index": idx, **resolution_trace}, http_status=400, clickup_response={"error": msg}, request_params=item_params)
            continue

        extra = set(it.keys()) - {"taskId", "taskName", "listName"}
        if extra:
            failed += 1
            errors_by_type["VALIDATION_ERROR"] = errors_by_type.get("VALIDATION_ERROR", 0) + 1
            msg = f"tasks[{idx}] has unexpected fields: {sorted(list(extra))}"
            per_item.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": msg}})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace={"item_index": idx, **resolution_trace}, http_status=400, clickup_response={"error": msg}, request_params=item_params)
            continue

        taskId = it.get("taskId")
        taskName = it.get("taskName")
        listName = it.get("listName")
        if taskId is None and not (isinstance(taskName, str) and taskName.strip() and isinstance(listName, str) and listName.strip()):
            failed += 1
            errors_by_type["VALIDATION_ERROR"] = errors_by_type.get("VALIDATION_ERROR", 0) + 1
            msg = "Each item must include taskId or (taskName and listName)"
            per_item.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": msg}})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace={"item_index": idx, **resolution_trace}, http_status=400, clickup_response={"error": msg}, request_params=item_params)
            continue
        if taskId is not None and (not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]+$", taskId)):
            failed += 1
            errors_by_type["VALIDATION_ERROR"] = errors_by_type.get("VALIDATION_ERROR", 0) + 1
            msg = "taskId must match pattern ^cu_tsk_[0-9A-Z]+$"
            per_item.append({"index": idx, "status": "error", "error": {"code": "VALIDATION_ERROR", "message": msg}})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace={"item_index": idx, **resolution_trace}, http_status=400, clickup_response={"error": msg}, request_params=item_params)
            continue

        trace = {"item_index": idx, **resolution_trace}
        task_row = None
        if taskId is not None:
            if taskId in done_task_ids:
                per_item.append({"index": idx, "status": "skipped", "reason": "already_processed", "taskId": taskId})
                continue
            task_row = tasks_by_id.get(taskId)
            trace["taskId"] = taskId
            if not task_row or task_row.get("status") == "deleted":
                failed += 1
                errors_by_type["NOT_FOUND"] = errors_by_type.get("NOT_FOUND", 0) + 1
                msg = "Task not found"
                per_item.append({"index": idx, "status": "error", "error": {"code": "NOT_FOUND", "message": msg}, "taskId": taskId})
                _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=404, clickup_response={"error": msg}, request_params=item_params)
                continue
        else:
            lst, lst_trace, lst_err = _resolve_list_by_name_scoped(listName)
            trace["sourceList_resolution"] = lst_trace
            if lst_err == "NOT_FOUND":
                failed += 1
                errors_by_type["NOT_FOUND"] = errors_by_type.get("NOT_FOUND", 0) + 1
                msg = "Source list not found for listName"
                per_item.append({"index": idx, "status": "error", "error": {"code": "NOT_FOUND", "message": msg}, "listName": listName})
                _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=404, clickup_response={"error": msg}, request_params=item_params)
                continue
            if lst_err == "CONFLICT":
                failed += 1
                errors_by_type["CONFLICT"] = errors_by_type.get("CONFLICT", 0) + 1
                msg = "Ambiguous source listName; provide taskId"
                per_item.append({"index": idx, "status": "error", "error": {"code": "CONFLICT", "message": msg}, "listName": listName})
                _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=409, clickup_response={"error": msg}, request_params=item_params)
                continue
            matches = [t for t in tasks_store if t.get("status") != "deleted" and t.get("list_node_id") == lst.get("id") and t.get("name") == taskName]
            trace["taskName"] = taskName
            if len(matches) == 0:
                failed += 1
                errors_by_type["NOT_FOUND"] = errors_by_type.get("NOT_FOUND", 0) + 1
                msg = "Task not found in source list"
                per_item.append({"index": idx, "status": "error", "error": {"code": "NOT_FOUND", "message": msg}, "taskName": taskName, "listName": listName})
                _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=404, clickup_response={"error": msg}, request_params=item_params)
                continue
            if len(matches) > 1:
                failed += 1
                errors_by_type["CONFLICT"] = errors_by_type.get("CONFLICT", 0) + 1
                msg = "Ambiguous taskName within source list; provide taskId"
                per_item.append({"index": idx, "status": "error", "error": {"code": "CONFLICT", "message": msg}, "taskName": taskName, "listName": listName})
                _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=409, clickup_response={"error": msg}, request_params=item_params)
                continue
            task_row = matches[0]
            trace["taskId"] = task_row.get("id")

        # Enforce destination list exists (already) and task is active
        if task_row.get("status") == "deleted":
            failed += 1
            errors_by_type["NOT_FOUND"] = errors_by_type.get("NOT_FOUND", 0) + 1
            msg = "Task is deleted"
            per_item.append({"index": idx, "status": "error", "error": {"code": "NOT_FOUND", "message": msg}, "taskId": task_row.get("id")})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=404, clickup_response={"error": msg}, request_params=item_params)
            continue

        # Move: workspace must remain consistent with destination list workspace (ClickUp would not cross-workspace)
        if task_row.get("workspace_id") != dest_workspace_id:
            failed += 1
            errors_by_type["CONFLICT"] = errors_by_type.get("CONFLICT", 0) + 1
            msg = "Cannot move task across workspaces"
            per_item.append({"index": idx, "status": "error", "error": {"code": "CONFLICT", "message": msg}, "taskId": task_row.get("id")})
            _log("error", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=409, clickup_response={"error": msg}, request_params=item_params)
            continue

        # Detect possible status mismatch and null it (warning)
        src_list = next((n for n in nodes if n.get("id") == task_row.get("list_node_id")), None)
        src_statuses = (src_list.get("vendor_metadata") or {}).get("statuses") if src_list else None
        warn = None
        if src_statuses is not None and dest_statuses is not None and src_statuses != dest_statuses:
            # reset status_value
            if task_row.get("status_value") is not None:
                task_row["status_value"] = None
                warn = "Destination list has different statuses; status_value was reset to null"
                warnings_accum.append(warn)

        # Apply move
        task_row["list_node_id"] = target_list.get("id")
        task_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tasks.json", tasks_store)

        succeeded += 1
        per_item.append({"index": idx, "status": "success", "taskId": task_row.get("id"), "warning": warn})
        _log("success", workspace_id=dest_workspace_id, bulk_job_id=bulk_job_id, resolution_trace=trace, http_status=200, warnings=[warn] if warn else None, clickup_request={"method": "POST", "endpoint": "/task/{task_id}/move", "body": {"destination_list_id": target_list.get("clickup_node_id")}}, clickup_response={"ok": True}, request_params=item_params)
        done_task_ids.add(task_row.get("id"))

    job["result_summary"] = {
        "succeeded": succeeded,
        "failed": failed,
        "errors_by_type": errors_by_type,
        "items": per_item,
    }
    job["status"] = "completed" if failed == 0 else "failed"
    job["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["updated_at"] = job["finished_at"]
    _save("bulk_jobs.json", bulk_jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"bulkJob": job, "warnings": warnings_accum or None, "meta": {"latency_ms": latency_ms}}

def create_list(name, spaceId=None, spaceName=None, content=None, archived=None, overrideStatuses=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    nodes = _load("nodes.json")
    workspaces = _load("workspaces.json")
    resolution_trace = {}

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "create_list",
            "bulk_job_id": None,
            "request_params": {"spaceId": spaceId, "spaceName": spaceName, "name": name, "content": content, "archived": archived, "overrideStatuses": overrideStatuses},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/space/{space_id}/list", "method": "POST", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if not isinstance(name, str) or not name.strip():
        _log("error", None, 400, {"error": "invalid_name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if spaceId is None and spaceName is None:
        _log("error", None, 400, {"error": "missing_space"})
        return _err("VALIDATION_ERROR", "Either spaceId or spaceName must be provided.", fields=["spaceId", "spaceName"])
    if content is not None and not isinstance(content, str):
        _log("error", None, 400, {"error": "invalid_content"})
        return _err("VALIDATION_ERROR", "content must be a string.", field="content")
    if archived is not None and not isinstance(archived, bool):
        _log("error", None, 400, {"error": "invalid_archived"})
        return _err("VALIDATION_ERROR", "archived must be a boolean.", field="archived")
    if overrideStatuses is not None and not isinstance(overrideStatuses, bool):
        _log("error", None, 400, {"error": "invalid_overrideStatuses"})
        return _err("VALIDATION_ERROR", "overrideStatuses must be a boolean.", field="overrideStatuses")

    # Resolve space
    space_node = None
    if spaceId is not None:
        if not isinstance(spaceId, str) or not spaceId.strip():
            _log("error", None, 400, {"error": "invalid_spaceId"})
            return _err("VALIDATION_ERROR", "spaceId must be a non-empty string.", field="spaceId")
        s = spaceId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            space_node = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "space" and n.get("status") != "deleted"), None)
        else:
            # allow vendor id
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "space" and n.get("status") != "deleted"]
            if len(candidates) == 1:
                space_node = candidates[0]
                resolution_trace["spaceId(vendor)->spaceNodeId"] = {"clickup_node_id": s, "id": space_node.get("id")}
            elif len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_spaceId_vendor"})
                return _err("CONFLICT", "Ambiguous spaceId (vendor id). Provide local spaceId.", spaceId=s, matches=[c.get("id") for c in candidates])
        if not space_node:
            _log("error", None, 404, {"error": "space_not_found"})
            return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)
    else:
        if not isinstance(spaceName, str) or not spaceName.strip():
            _log("error", None, 400, {"error": "invalid_spaceName"})
