        space_node = candidates[0]
        resolution_trace["spaceName->spaceId"] = {"spaceName": spaceName, "id": space_node.get("id")}

    # Create list node
    new_node_id = _new_id("cu_nod_", nodes)
    clickup_node_id = f"cl_{_new_id('', [{'id':'X'}])[0:12].lower()}"
    row = {
