        "updated_at": now,
    }

    # constraints: content only for list (ok), override_statuses only for folder -> keep null
    nodes.append(row)
    _save("nodes.json", nodes)

    _log("success", space_node.get("workspace_id"), 200, {"id": clickup_node_id})
    return {"list": row, "resolution_trace": resolution_trace or None}

def create_list_in_folder(name, folderId=None, folderName=None, spaceId=None, spaceName=None, content=None, archived=None, overrideStatuses=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
