    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "create_list_in_folder",
            "bulk_job_id": None,
            "request_params": {"folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName, "name": name, "content": content, "archived": archived, "overrideStatuses": overrideStatuses},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/folder/{folder_id}/list", "method": "POST", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if not isinstance(name, str) or not name.strip():
        _log("error", None, 400, {"error": "invalid_name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if folderId is None and folderName is None:
        _log("error", None, 400, {"error": "missing_folder"})
        return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.", fields=["folderId", "folderName"])
    if folderId is None and folderName is not None and spaceId is None and spaceName is None:
        _log("error", None, 400, {"error": "missing_space_scope"})
        return _err("VALIDATION_ERROR", "spaceId or spaceName is required when resolving folderName.", fields=["spaceId", "spaceName"])
    if content is not None and not isinstance(content, str):
        _log("error", None, 400, {"error": "invalid_content"})
        return _err("VALIDATION_ERROR", "content must be a string.", field="content")
    if archived is not None and not isinstance(archived, bool):
        _log("error", None, 400, {"error": "invalid_archived"})
        return _err("VALIDATION_ERROR", "archived must be a boolean.", field="archived")
    if overrideStatuses is not None and not isinstance(overrideStatuses, bool):
        _log("error", None, 400, {"error": "invalid_overrideStatuses"})
        return _err("VALIDATION_ERROR", "overrideStatuses must be a boolean.", field="overrideStatuses")

    # Resolve space (if needed)
    space_node = None
    if spaceId is not None:
        if not isinstance(spaceId, str) or not spaceId.strip():
            _log("error", None, 400, {"error": "invalid_spaceId"})
            return _err("VALIDATION_ERROR", "spaceId must be a non-empty string.", field="spaceId")
        s = spaceId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            space_node = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "space" and n.get("status") != "deleted"), None)
        else:
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "space" and n.get("status") != "deleted"]
            if len(candidates) == 1:
                space_node = candidates[0]
                resolution_trace["spaceId(vendor)->spaceNodeId"] = {"clickup_node_id": s, "id": space_node.get("id")}
            elif len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_spaceId_vendor"})
                return _err("CONFLICT", "Ambiguous spaceId (vendor id). Provide local spaceId.", spaceId=s, matches=[c.get("id") for c in candidates])
        if spaceId is not None and not space_node:
            _log("error", None, 404, {"error": "space_not_found"})
            return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)

    if space_node is None and spaceName is not None:
        if not isinstance(spaceName, str) or not spaceName.strip():
            _log("error", None, 400, {"error": "invalid_spaceName"})
            return _err("VALIDATION_ERROR", "spaceName must be a non-empty string.", field="spaceName")
        candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "space" and n.get("status") != "deleted" and (n.get("name") or "").strip() == spaceName.strip()]
        if len(candidates) == 0:
            _log("error", None, 404, {"error": "space_not_found_by_name"})
            return _err("NOT_FOUND", "Space not found.", spaceName=spaceName)
        if len(candidates) > 1:
            _log("error", None, 409, {"error": "ambiguous_spaceName"})
            return _err("CONFLICT", "Ambiguous spaceName; provide spaceId to disambiguate.", spaceName=spaceName, matches=[c.get("id") for c in candidates])
        space_node = candidates[0]
        resolution_trace["spaceName->spaceId"] = {"spaceName": spaceName, "id": space_node.get("id")}

    # Resolve folder
    folder_node = None
    if folderId is not None:
        if not isinstance(folderId, str) or not folderId.strip():
            _log("error", None, 400, {"error": "invalid_folderId"})
            return _err("VALIDATION_ERROR", "folderId must be a non-empty string.", field="folderId")
        s = folderId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            folder_node = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "folder" and n.get("status") != "deleted"), None)
        else:
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("clickup_node_id") == s and n.get("node_type") == "folder" and n.get("status") != "deleted"]
            if len(candidates) == 1:
                folder_node = candidates[0]
                resolution_trace["folderId(vendor)->folderNodeId"] = {"clickup_node_id": s, "id": folder_node.get("id")}
            elif len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_folderId_vendor"})
                return _err("CONFLICT", "Ambiguous folderId (vendor id). Provide local folderId.", folderId=s, matches=[c.get("id") for c in candidates])
        if not folder_node:
            _log("error", None, 404, {"error": "folder_not_found"})
            return _err("NOT_FOUND", "Folder not found.", folderId=folderId)
    else:
        # folderName must be scoped by space
        if not isinstance(folderName, str) or not folderName.strip():
            _log("error", None, 400, {"error": "invalid_folderName"})
            return _err("VALIDATION_ERROR", "folderName must be a non-empty string.", field="folderName")
        if space_node is None:
            _log("error", None, 400, {"error": "missing_space_scope"})
            return _err("VALIDATION_ERROR", "spaceId or spaceName is required when resolving folderName.", fields=["spaceId", "spaceName"])
        candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "folder" and n.get("status") != "deleted" and n.get("parent_node_id") == space_node.get("id") and (n.get("name") or "").strip() == folderName.strip()]
        if len(candidates) == 0:
            _log("error", space_node.get("workspace_id"), 404, {"error": "folder_not_found_by_name"})
            return _err("NOT_FOUND", "Folder not found.", folderName=folderName, spaceId=space_node.get("id"))
        if len(candidates) > 1:
            _log("error", space_node.get("workspace_id"), 409, {"error": "ambiguous_folderName"})
            return _err("CONFLICT", "Ambiguous folderName within space; provide folderId.", folderName=folderName, matches=[c.get("id") for c in candidates])
        folder_node = candidates[0]
        resolution_trace["folderName->folderId"] = {"folderName": folderName, "id": folder_node.get("id")}

    # If both space scope and folder are present, enforce folder belongs to that space
    if space_node is not None and folder_node.get("parent_node_id") != space_node.get("id"):
        _log("error", folder_node.get("workspace_id"), 409, {"error": "folder_space_mismatch"})
        return _err("CONFLICT", "folder does not belong to the specified space.", folderId=folder_node.get("id"), spaceId=space_node.get("id"))

    # Create list under folder
    new_node_id = _new_id("cu_nod_", nodes)
    clickup_node_id = f"cl_{_new_id('', [{'id':'X'}])[0:12].lower()}"
    row = {
        "id": new_node_id,
        "workspace_id": folder_node.get("workspace_id"),
        "parent_node_id": folder_node.get("id"),
        "node_type": "list",
        "clickup_node_id": clickup_node_id,
        "name": name.strip(),
        "content": content if content is not None else None,
        "archived": bool(archived) if archived is not None else False,
        "override_statuses": None,
        "status": "archived" if (archived is True) else "active",
        "vendor_metadata": {"override_statuses": overrideStatuses} if overrideStatuses is not None else None,
        "created_at": now,
        "updated_at": now,
    }
    nodes.append(row)
    _save("nodes.json", nodes)

    _log("success", folder_node.get("workspace_id"), 200, {"id": clickup_node_id})
    return {"list": row, "resolution_trace": resolution_trace or None}

