def update_list(listId=None, listName=None, name=None, content=None, status=None, archived=None, overrideStatuses=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, workspace_id=None, http_status=None, resolution_trace=None, warnings=None, clickup_request=None, clickup_response=None):
        op_log = _load("operation_log.json")
        op_id = "op_" + uuid.uuid4().hex
        entry = {
            "id": op_id,
            "workspace_id": workspace_id,
            "tool_name": "update_list",
            "bulk_job_id": None,
            "request_params": {
                "listId": listId,
                "listName": listName,
                "name": name,
                "content": content,
                "status": status,
                "archived": archived,
                "overrideStatuses": overrideStatuses,
            },
            "resolution_trace": resolution_trace,
            "clickup_request": clickup_request,
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings,
            "status": status_out,
            "created_at": now,
            "updated_at": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    try:
        if listId is None and listName is None:
            _log("error", resolution_trace={"validation": "missing_identifier"}, http_status=400)
            return _err("VALIDATION_ERROR", "Either 'listId' or 'listName' must be provided.", fields=["listId", "listName"])

        # At least one update field must be provided
        if name is None and content is None and status is None and archived is None and overrideStatuses is None:
            _log("error", resolution_trace={"validation": "no_update_fields"}, http_status=400)
            return _err("VALIDATION_ERROR", "At least one updatable field must be provided.", fields=["name", "content", "status", "archived", "overrideStatuses"])

        pat = re.compile(r"^cu_nod_[0-9A-Z]+$")
        if listId is not None and (not isinstance(listId, str) or not pat.match(listId)):
            _log("error", resolution_trace={"validation": "listId"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'listId' must match pattern ^cu_nod_[0-9A-Z]+$.", field="listId")

        if listName is not None and (not isinstance(listName, str) or listName.strip() == ""):
            _log("error", resolution_trace={"validation": "listName"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'listName' must be a non-empty string when provided.", field="listName")

        if name is not None and (not isinstance(name, str) or name.strip() == ""):
            _log("error", resolution_trace={"validation": "name"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'name' must be a non-empty string when provided.", field="name")

        if content is not None and not isinstance(content, str):
            _log("error", resolution_trace={"validation": "content"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'content' must be a string when provided.", field="content")

        if archived is not None and not isinstance(archived, bool):
            _log("error", resolution_trace={"validation": "archived"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'archived' must be a boolean when provided.", field="archived")

        if overrideStatuses is not None and not isinstance(overrideStatuses, bool):
            _log("error", resolution_trace={"validation": "overrideStatuses"}, http_status=400)
            return _err("VALIDATION_ERROR", "Field 'overrideStatuses' must be a boolean when provided.", field="overrideStatuses")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                _log("error", resolution_trace={"validation": "status"}, http_status=400)
                return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, archived, deleted.", field="status")

        nodes = _load("nodes.json")
        tasks = _load("tasks.json")
        workspaces = _load("workspaces.json")

        resolution_trace = {"list": None}
        list_node = None

        if listId is not None:
            list_node = next((n for n in nodes if n.get("id") == listId and n.get("node_type") == "list"), None)
            resolution_trace["list"] = {"by": "listId", "listId": listId, "resolved": bool(list_node)}
            if not list_node or list_node.get("status") == "deleted":
                _log("error", resolution_trace=resolution_trace, http_status=404, clickup_response={"error": "list_not_found"})
                return _err("NOT_FOUND", "List not found.", listId=listId)
        else:
            matches = [n for n in nodes if n.get("node_type") == "list" and n.get("status") != "deleted" and n.get("name") == listName]
            resolution_trace["list"] = {"by": "listName", "listName": listName, "match_count": len(matches)}
            if len(matches) == 0:
                _log("error", resolution_trace=resolution_trace, http_status=404)
                return _err("NOT_FOUND", "List not found for provided listName.", listName=listName)
            if len(matches) > 1:
                _log("error", resolution_trace=resolution_trace, http_status=404)
                return _err("NOT_FOUND", "Ambiguous listName; multiple lists matched. Provide listId.", listName=listName, matches=[m.get("id") for m in matches])
            list_node = matches[0]
            resolution_trace["list"]["listId"] = list_node.get("id")

        workspace_id = list_node.get("workspace_id")
        ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("status") != "deleted"), None)
        if not ws:
            _log("error", workspace_id=workspace_id, resolution_trace=resolution_trace, http_status=404)
            return _err("NOT_FOUND", "Workspace for list not found.", workspace_id=workspace_id)

        # Apply mutations (only provided fields)
        warnings = []

        if name is not None:
            list_node["name"] = name.strip()

        if content is not None:
            list_node["content"] = content

        if archived is not None:
            list_node["archived"] = archived
            # keep local cache lifecycle consistent with archived flag unless explicitly overridden by status
            if status is None and list_node.get("status") != "deleted":
                list_node["status"] = "archived" if archived else "active"

        if overrideStatuses is not None:
            list_node["override_statuses"] = overrideStatuses

        # Lifecycle transition enforcement for node.status
        if status is not None:
            current = list_node.get("status")
            transitions = {
                "active": ["archived", "deleted"],
                "archived": ["active", "deleted"],
                "deleted": [],
            }
            if current != status:
                if status not in transitions.get(current, []):
                    _log("error", workspace_id=workspace_id, resolution_trace={**resolution_trace, "transition": {"from": current, "to": status}}, http_status=409)
                    return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=current, to_status=status)
                list_node["status"] = status
                # Permanent delete rule: deleted must not transition back (already enforced by transitions)
                if status == "deleted":
                    # For parity with delete_list business rule: mark tasks under list as deleted as well
                    affected = 0
                    for t in tasks:
                        if t.get("list_node_id") == list_node.get("id") and t.get("status") != "deleted":
                            t["status"] = "deleted"
                            t["updated_at"] = now
                            affected += 1
                    if affected:
                        _save("tasks.json", tasks)

        list_node["updated_at"] = now

        # Persist nodes
        _save("nodes.json", nodes)

        # Touch workspace updated_at
        for w in workspaces:
            if w.get("id") == workspace_id:
                w["updated_at"] = now
                break
        _save("workspaces.json", workspaces)

        _log("success", workspace_id=workspace_id, resolution_trace=resolution_trace, warnings=warnings or None, http_status=200)
        return {"list": list_node, "warnings": warnings or []}
    except Exception as e:
        _log("error", resolution_trace={"exception": type(e).__name__}, http_status=500, clickup_response={"error": str(e)})
        return _err("CONFLICT", "Unexpected server error.")

