        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "delete_list",
            "bulk_job_id": None,
            "request_params": {"listId": listId, "listName": listName},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/list/{list_id}", "method": "DELETE", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if listId is None and listName is None:
        _log("error", None, 400, {"error": "missing_identifier"})
        return _err("VALIDATION_ERROR", "Either listId or listName must be provided.", fields=["listId", "listName"])

    list_node = None
    if listId is not None:
        if not isinstance(listId, str) or not listId.strip():
            _log("error", None, 400, {"error": "invalid_listId"})
            return _err("VALIDATION_ERROR", "listId must be a non-empty string.", field="listId")
        s = listId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            list_node = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "list"), None)
        else:
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "list" and n.get("clickup_node_id") == s]
            if len(candidates) == 1:
                list_node = candidates[0]
                resolution_trace["listId(vendor)->listNodeId"] = {"clickup_node_id": s, "id": list_node.get("id")}
            elif len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_listId_vendor"})
                return _err("CONFLICT", "Ambiguous listId (vendor id) matched multiple lists; provide local listId.", listId=s, matches=[c.get("id") for c in candidates])
        if not list_node:
            _log("error", None, 404, {"error": "list_not_found"})
            return _err("NOT_FOUND", "List not found.", listId=listId)
    else:
        if not isinstance(listName, str) or not listName.strip():
            _log("error", None, 400, {"error": "invalid_listName"})
            return _err("VALIDATION_ERROR", "listName must be a non-empty string.", field="listName")
        candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "list" and (n.get("name") or "").strip() == listName.strip()]
        if len(candidates) == 0:
            _log("error", None, 404, {"error": "list_not_found_by_name"})
            return _err("NOT_FOUND", "List not found.", listName=listName)
        if len(candidates) > 1:
            _log("error", None, 409, {"error": "ambiguous_listName"})
            return _err("CONFLICT", "Ambiguous listName; provide listId to disambiguate.", listName=listName, matches=[c.get("id") for c in candidates])
        list_node = candidates[0]
        resolution_trace["listName->listId"] = {"listName": listName, "id": list_node.get("id")}

    # Permanent delete: transition to deleted; idempotent if already deleted
    if list_node.get("status") == "deleted":
        # Still ensure tasks are deleted as per rule (idempotent)
        changed = False
        for t in tasks_store:
            if isinstance(t, dict) and t.get("list_node_id") == list_node.get("id") and t.get("status") != "deleted":
                t["status"] = "deleted"
                t["updated_at"] = now
                changed = True
        if changed:
            _save("tasks.json", tasks_store)
        _log("success", list_node.get("workspace_id"), 200, {"deleted": True, "already_deleted": True})
        return {"list": list_node, "deleted": True, "already_deleted": True}

    # Apply lifecycle transition
    list_node["status"] = "deleted"
    list_node["updated_at"] = now

    # Cascade: mark tasks deleted
    affected_tasks = 0
    for t in tasks_store:
        if isinstance(t, dict) and t.get("list_node_id") == list_node.get("id") and t.get("status") != "deleted":
            t["status"] = "deleted"
            t["updated_at"] = now
            affected_tasks += 1

    _save("nodes.json", nodes)
    _save("tasks.json", tasks_store)

    _log("success", list_node.get("workspace_id"), 200, {"deleted": True, "tasks_deleted": affected_tasks})
    return {"list": list_node, "deleted": True, "tasks_deleted": affected_tasks}

