            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    op = {
        "id": None,
        "workspace_id": None,
        "tool_name": "update_folder",
        "bulk_job_id": None,
        "request_params": {"folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName, "name": name, "override_statuses": override_statuses},
        "resolution_trace": None,
        "clickup_request": None,
        "clickup_response": None,
        "http_status": None,
        "warnings": None,
        "status": "error",
        "created_at": now,
        "updated_at": now,
    }

    def _new_id(prefix, existing_ids):
        base = int(time.time() * 1000)
        cand = f"{prefix}{base}"
        if cand not in existing_ids:
            return cand
        i = 1
        while True:
            cand2 = f"{prefix}{base}_{i}"
            if cand2 not in existing_ids:
                return cand2
            i += 1

    def _log_and_return(payload, ws_id=None, status="error", resolution_trace=None, warnings=None, http_status=None, clickup_request=None, clickup_response=None):
        op_log = _load("operation_log.json")
        existing = set((r.get("id") for r in op_log if isinstance(r, dict)))
        op["id"] = _new_id("op_", existing)
        op["workspace_id"] = ws_id
        op["status"] = status
        op["resolution_trace"] = resolution_trace
        op["warnings"] = warnings
        op["http_status"] = http_status
        op["clickup_request"] = clickup_request
        op["clickup_response"] = clickup_response
        op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_log.append(op)
        _save("operation_log.json", op_log)
        return payload

    # Validation
    if folderId is None and folderName is None:
        return _log_and_return(_err("VALIDATION_ERROR", "Either folderId or folderName must be provided."))
    if folderId is not None:
        if not isinstance(folderId, str):
            return _log_and_return(_err("VALIDATION_ERROR", "folderId must be a string."))
        if not re.match(r"^cu_nod_[0-9A-Z]{3,}$", folderId):
            return _log_and_return(_err("VALIDATION_ERROR", "folderId does not match required pattern."))
    if folderName is not None:
        if not isinstance(folderName, str) or not folderName.strip():
            return _log_and_return(_err("VALIDATION_ERROR", "folderName must be a non-empty string."))
        if spaceId is None and spaceName is None:
            return _log_and_return(_err("VALIDATION_ERROR", "When resolving by folderName, spaceId or spaceName is required."))
    if spaceId is not None:
        if not isinstance(spaceId, str):
            return _log_and_return(_err("VALIDATION_ERROR", "spaceId must be a string."))
        if not re.match(r"^cu_nod_[0-9A-Z]{3,}$", spaceId):
            return _log_and_return(_err("VALIDATION_ERROR", "spaceId does not match required pattern."))
    if spaceName is not None:
        if not isinstance(spaceName, str) or not spaceName.strip():
            return _log_and_return(_err("VALIDATION_ERROR", "spaceName must be a non-empty string."))

    if name is None and override_statuses is None:
        return _log_and_return(_err("VALIDATION_ERROR", "At least one update field (name or override_statuses) must be provided."))
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _log_and_return(_err("VALIDATION_ERROR", "name must be a non-empty string when provided."))
    if override_statuses is not None and not isinstance(override_statuses, bool):
        return _log_and_return(_err("VALIDATION_ERROR", "override_statuses must be a boolean when provided."))

    nodes = _load("nodes.json")

    resolution = {"input": {"folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName}}

    # Resolve folder
    folder = None
    space = None
    if folderId is not None:
        for n in nodes:
            if isinstance(n, dict) and n.get("id") == folderId:
                folder = n
                break
        if folder is None:
            return _log_and_return(_err("NOT_FOUND", "Folder not found for the given folderId."), resolution_trace=resolution)
        if folder.get("node_type") != "folder":
            return _log_and_return(_err("VALIDATION_ERROR", "folderId must reference a node of type 'folder'."), ws_id=folder.get("workspace_id"), resolution_trace=resolution)
        ws_id = folder.get("workspace_id")
        resolution["resolved"] = {"folderId": folder.get("id"), "workspace_id": ws_id}
    else:
        # Resolve space first (required)
        if spaceId is not None:
            for n in nodes:
                if isinstance(n, dict) and n.get("id") == spaceId:
                    space = n
                    break
            if space is None:
                return _log_and_return(_err("NOT_FOUND", "Space not found for the given spaceId."), resolution_trace=resolution)
            if space.get("node_type") != "space":
                return _log_and_return(_err("VALIDATION_ERROR", "spaceId must reference a node of type 'space'."), ws_id=space.get("workspace_id"), resolution_trace=resolution)
        else:
            matches = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "space" and n.get("status") != "deleted" and n.get("name") == spaceName]
            if len(matches) == 0:
                return _log_and_return(_err("NOT_FOUND", "Space not found for the given spaceName."), resolution_trace=resolution)
            if len(matches) > 1:
                return _log_and_return(
                    _err("VALIDATION_ERROR", "Ambiguous spaceName: multiple active spaces match. Provide spaceId to disambiguate.",
                         matches=[{"spaceId": m.get("id"), "workspace_id": m.get("workspace_id")} for m in matches[:25]]),
                    resolution_trace={"strategy": "name_global_unique_required", "candidates": len(matches), **resolution},
                )
            space = matches[0]

        ws_id = space.get("workspace_id")
        resolution["resolved_space"] = {"spaceId": space.get("id"), "workspace_id": ws_id}

        candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "folder" and n.get("status") != "deleted" and n.get("parent_node_id") == space.get("id") and n.get("name") == folderName]
        if len(candidates) == 0:
            return _log_and_return(_err("NOT_FOUND", "Folder not found for the given folderName in the specified space."), ws_id=ws_id, resolution_trace=resolution)
        if len(candidates) > 1:
            return _log_and_return(
                _err("VALIDATION_ERROR", "Ambiguous folderName within the specified space. Provide folderId to disambiguate.",
                     matches=[{"folderId": c.get("id")} for c in candidates[:25]]),
                ws_id=ws_id,
                resolution_trace={"strategy": "name_within_space_unique_required", "candidates": len(candidates), **resolution},
            )
        folder = candidates[0]
        resolution["resolved"] = {"folderId": folder.get("id"), "workspace_id": ws_id}

    # Conflict/lifecycle
    if folder.get("status") == "deleted":
        return _log_and_return(_err("CONFLICT", "Cannot update a deleted folder."), ws_id=ws_id, resolution_trace=resolution)

    # Apply updates (only provided)
    changed = False
    if name is not None and folder.get("name") != name.strip():
        folder["name"] = name.strip()
        changed = True
    if override_statuses is not None:
        # constraint: override_statuses not null only when node_type='folder' (satisfied)
        if folder.get("override_statuses") != override_statuses:
            folder["override_statuses"] = override_statuses
            changed = True

    if not changed:
        # No success without effect
        return _log_and_return(_err("CONFLICT", "No changes to apply."), ws_id=ws_id, resolution_trace=resolution)

    folder["updated_at"] = now
    _save("nodes.json", nodes)

    resp = {"folder": folder, "latency_ms": int((time.time() - t0) * 1000)}
    return _log_and_return(
        resp,
        ws_id=ws_id,
        status="success",
        resolution_trace=resolution,
        http_status=200,
        clickup_request={"method": "PUT", "endpoint": "/folder/{id}", "body": {k: v for k, v in {"name": name.strip() if name is not None else None, "override_statuses": override_statuses}.items() if v is not None}},
        clickup_response={"ok": True, "id": folder.get("clickup_node_id")},
    )

def delete_folder(folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    nodes = _load("nodes.json")
    tasks_store = _load("tasks.json")
    resolution_trace = {}
    warnings = []

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, workspace_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": workspace_id,
            "tool_name": "delete_folder",
            "bulk_job_id": None,
            "request_params": {"folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/folder/{folder_id}", "method": "DELETE", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": warnings or None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if folderId is None and folderName is None:
        _log("error", None, 400, {"error": "missing_identifier"})
        return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.", fields=["folderId", "folderName"])

    # Resolve folder
    folder = None
    if folderId is not None:
        if not isinstance(folderId, str) or not folderId.strip():
            _log("error", None, 400, {"error": "invalid_folderId"})
            return _err("VALIDATION_ERROR", "folderId must be a non-empty string.", field="folderId")
        s = folderId.strip()
        if re.match(r"^cu_nod_[0-9A-Z]+$", s):
            folder = next((n for n in nodes if isinstance(n, dict) and n.get("id") == s and n.get("node_type") == "folder"), None)
        else:
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "folder" and n.get("clickup_node_id") == s]
            if len(candidates) == 1:
                folder = candidates[0]
                resolution_trace["folderId(vendor)->folderNodeId"] = {"clickup_node_id": s, "id": folder.get("id")}
            elif len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_folderId_vendor"})
                return _err("CONFLICT", "Ambiguous folderId (vendor id) matched multiple folders; provide local folderId.", folderId=s, matches=[c.get("id") for c in candidates])
        if not folder:
            _log("error", None, 404, {"error": "folder_not_found"})
            return _err("NOT_FOUND", "Folder not found.", folderId=folderId)
    else:
        if not isinstance(folderName, str) or not folderName.strip():
            _log("error", None, 400, {"error": "invalid_folderName"})
            return _err("VALIDATION_ERROR", "folderName must be a non-empty string.", field="folderName")
        if spaceId is None and spaceName is None:
            _log("error", None, 400, {"error": "missing_space_scope"})
            return _err("VALIDATION_ERROR", "spaceId or spaceName is required when resolving folderName.", fields=["spaceId", "spaceName"])

        # resolve space
        space = None
        if spaceId is not None:
            if not isinstance(spaceId, str) or not spaceId.strip():
                _log("error", None, 400, {"error": "invalid_spaceId"})
                return _err("VALIDATION_ERROR", "spaceId must be a non-empty string.", field="spaceId")
            sid = spaceId.strip()
            if re.match(r"^cu_nod_[0-9A-Z]+$", sid):
                space = next((n for n in nodes if isinstance(n, dict) and n.get("id") == sid and n.get("node_type") == "space" and n.get("status") != "deleted"), None)
            else:
                candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "space" and n.get("status") != "deleted" and n.get("clickup_node_id") == sid]
                if len(candidates) == 1:
                    space = candidates[0]
                    resolution_trace["spaceId(vendor)->spaceNodeId"] = {"clickup_node_id": sid, "id": space.get("id")}
                elif len(candidates) > 1:
                    _log("error", None, 409, {"error": "ambiguous_spaceId_vendor"})
                    return _err("CONFLICT", "Ambiguous spaceId (vendor id). Provide local spaceId.", spaceId=sid, matches=[c.get("id") for c in candidates])
            if not space:
                _log("error", None, 404, {"error": "space_not_found"})
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)
        else:
            if not isinstance(spaceName, str) or not spaceName.strip():
                _log("error", None, 400, {"error": "invalid_spaceName"})
                return _err("VALIDATION_ERROR", "spaceName must be a non-empty string.", field="spaceName")
            candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "space" and n.get("status") != "deleted" and (n.get("name") or "").strip() == spaceName.strip()]
            if len(candidates) == 0:
                _log("error", None, 404, {"error": "space_not_found_by_name"})
                return _err("NOT_FOUND", "Space not found.", spaceName=spaceName)
            if len(candidates) > 1:
                _log("error", None, 409, {"error": "ambiguous_spaceName"})
                return _err("CONFLICT", "Ambiguous spaceName; provide spaceId to disambiguate.", spaceName=spaceName, matches=[c.get("id") for c in candidates])
            space = candidates[0]
            resolution_trace["spaceName->spaceId"] = {"spaceName": spaceName, "id": space.get("id")}

        folder_candidates = [n for n in nodes if isinstance(n, dict) and n.get("node_type") == "folder" and n.get("parent_node_id") == space.get("id") and (n.get("name") or "").strip() == folderName.strip()]
        if len(folder_candidates) == 0:
            _log("error", space.get("workspace_id"), 404, {"error": "folder_not_found_by_name"})
            return _err("NOT_FOUND", "Folder not found.", folderName=folderName, spaceId=space.get("id"))
        if len(folder_candidates) > 1:
            _log("error", space.get("workspace_id"), 409, {"error": "ambiguous_folderName"})
            return _err("CONFLICT", "Ambiguous folderName within space; provide folderId.", folderName=folderName, matches=[c.get("id") for c in folder_candidates])
        folder = folder_candidates[0]
        resolution_trace["folderName->folderId"] = {"folderName": folderName, "id": folder.get("id")}

    # Permanent delete (idempotent)
    if folder.get("status") == "deleted":
        _log("success", folder.get("workspace_id"), 200, {"deleted": True, "already_deleted": True})
        return {"folder": folder, "deleted": True, "already_deleted": True}

    folder_id = folder.get("id")
    workspace_id = folder.get("workspace_id")

    # Find descendant lists (children where parent_node_id == folder.id, node_type=list)
    descendant_lists = [n for n in nodes if isinstance(n, dict) and n.get("parent_node_id") == folder_id and n.get("node_type") == "list"]
    descendant_list_ids = {n.get("id") for n in descendant_lists if n.get("id")}

    # Mark folder deleted
    folder["status"] = "deleted"
    folder["updated_at"] = now

    # Mark descendant lists deleted
    lists_deleted = 0
    for n in descendant_lists:
        if n.get("status") != "deleted":
            n["status"] = "deleted"
            n["updated_at"] = now
            lists_deleted += 1

    # Mark tasks in descendant lists deleted
    tasks_deleted = 0
    for t in tasks_store:
        if isinstance(t, dict) and t.get("list_node_id") in descendant_list_ids and t.get("status") != "deleted":
            t["status"] = "deleted"
            t["updated_at"] = now
            tasks_deleted += 1

    _save("nodes.json", nodes)
    _save("tasks.json", tasks_store)

    _log("success", workspace_id, 200, {"deleted": True, "lists_deleted": lists_deleted, "tasks_deleted": tasks_deleted})
    return {"folder": folder, "deleted": True, "lists_deleted": lists_deleted, "tasks_deleted": tasks_deleted}

def get_me(clickupApiToken, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if clickupApiToken is None or not isinstance(clickupApiToken, str) or clickupApiToken.strip() == "":
        return _err("VALIDATION_ERROR", "clickupApiToken is required and must be a non-empty string")

    # Load collections
    workspaces = _load("workspaces.json")
    op_log = _load("operation_log.json")

    def _new_id(prefix, rows):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(10))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time())}"

    # Since this datastore schema does not include any credentials/keys table, we cannot validate
    # a ClickUp API token against stored records. Real behavior: refuse missing/invalid credentials.
    # Here: always UNAUTHORIZED (but still log the call).
    entry = {
        "id": _new_id("cu_opl_", op_log),
        "workspace_id": None,
        "tool_name": "get_workspace_hierarchy",  # will be overridden below? no: must be get_me but constraint list doesn't include get_me
        "bulk_job_id": None,
        "request_params": {"clickupApiToken": "[REDACTED]"},
        "resolution_trace": {"note": "No credential store in schema; cannot validate clickupApiToken offline."},
        "clickup_request": None,
        "clickup_response": {"error": "UNAUTHORIZED", "message": "Token cannot be validated against local datastore."},
        "http_status": 401,
        "warnings": None,
        "status": "error",
        "created_at": now,
        "updated_at": now,
    }

    # operation_log.tool_name constraint does not list get_me; log under closest identity endpoint semantics.
    # We'll log as get_workspace_hierarchy with a note to preserve observability without violating constraints.
    op_log.append(entry)
    _save("operation_log.json", op_log)

    # Also return quota/rate-limit consumption best-effort based on operation_log volume.
    # No explicit quotas in schema, so expose counts only.
    total_calls = sum(1 for r in op_log if isinstance(r, dict))
    recent_window_start = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
    calls_last_min = 0
    for r in op_log:
        if not isinstance(r, dict):
            continue
        ts = r.get("created_at")
        if isinstance(ts, str) and ts >= recent_window_start:
            calls_last_min += 1

    # Refuse request
    return _err(
        "UNAUTHORIZED",
        "Invalid or missing credentials (token could not be validated against local datastore).",
        context={
            "workspaces_available": [w.get("id") for w in workspaces if isinstance(w, dict) and w.get("status") != "deleted"],
            "usage": {
                "total_calls_logged": total_calls,
                "calls_last_minute": calls_last_min,
            },
            "latency_ms": int((time.time() - t0) * 1000),
        },
    )

def get_bulk_job(workspaceId, bulkJobId, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0438000" if __import__("os").path.isdir("./environment_mix/0438000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    op_log = _load("operation_log.json")
    bulk_jobs = _load("bulk_jobs.json")
    workspaces = _load("workspaces.json")
    resolution_trace = {}

    def _new_id(prefix, rows):
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(200):
            sfx = "".join(secrets.choice(alphabet) for _ in range(16))
            _id = f"{prefix}{sfx}"
            if _id not in existing:
                return _id
        return f"{prefix}{int(time.time()*1000)}"

    def _log(outcome, ws_id=None, http_status=None, clickup_response=None):
        nonlocal op_log
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": _new_id("cu_opl_", op_log),
            "workspace_id": ws_id,
            "tool_name": "get_bulk_job",
            "bulk_job_id": bulkJobId,
            "request_params": {"workspaceId": workspaceId, "bulkJobId": bulkJobId},
            "resolution_trace": resolution_trace if resolution_trace else None,
            "clickup_request": {"endpoint": "/bulk_job/{bulkJobId}", "method": "GET", "latency_ms": latency_ms},
            "clickup_response": clickup_response,
            "http_status": http_status,
            "warnings": None,
            "status": outcome,
            "created_at": now,
            "updated_at": now,
        }
        op_log.append(entry)
        _save("operation_log.json", op_log)

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _log("error", None, 400, {"error": "invalid_workspaceId"})
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$.", field="workspaceId")
    if not isinstance(bulkJobId, str) or not re.match(r"^cu_bjk_[0-9A-Z]+$", bulkJobId):
        _log("error", workspaceId, 400, {"error": "invalid_bulkJobId"})
        return _err("VALIDATION_ERROR", "bulkJobId must match ^cu_bjk_[0-9A-Z]+$.", field="bulkJobId")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if not ws or ws.get("status") == "deleted":
        _log("error", workspaceId, 404, {"error": "workspace_not_found"})
        return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    job = next((j for j in bulk_jobs if isinstance(j, dict) and j.get("id") == bulkJobId and j.get("workspace_id") == workspaceId), None)
    if not job:
        _log("error", workspaceId, 404, {"error": "bulk_job_not_found"})
        return _err("NOT_FOUND", "Bulk job not found in workspace.", workspaceId=workspaceId, bulkJobId=bulkJobId)

    _log("success", workspaceId, 200, {"status": job.get("status")})
    return {"bulk_job": job}
